	 ('38113a70-cba6-4480-b758-6fd6551491da'::uuid,'01990b5c-6fd2-7f68-a950-3825e395dcc9'::uuid,'If a creature the aboleth can see communicates telepathically with the aboleth, the aboleth learns the creature''s greatest desires.','Probing Telepathy',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('8a8e874c-0542-441e-9048-cdb055b8652d'::uuid,'01990b5c-6fd2-7f68-a950-3825e395dcc9'::uuid,'The aboleth can breathe air and water.','Amphibious',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('9fa725b3-5301-4be0-9090-38f769b55d81'::uuid,'01990b5c-6fd2-7f68-a950-3825e395dcc9'::uuid,'While underwater, the aboleth is surrounded by mucus. Constitution Saving Throw: DC 14, each creature in a 5-foot Emanation originating from the aboleth at the end of the aboleth''s turn. Failure: The target is cursed. Until the curse ends, the target''s skin becomes slimy, the target can breathe air and water, and it can''t regain Hit Points unless it is underwater. While the cursed creature is outside a body of water, the creature takes 6 (1d12) Acid damage at the end of every 10 minutes unless moisture is applied to its skin before those minutes have passed.','Mucus Cloud',false,NULL,NULL,'d12','Acid',1,NULL,NULL,NULL),
	 ('e56d02c8-4c27-4a34-97db-bbbf5f1ad4be'::uuid,'01990b5c-6fd2-7f68-a950-3825e395dcc9'::uuid,'If destroyed, the aboleth gains a new body in 5d10 days, reviving with all its Hit Points in the Far Realm or another location chosen by the DM.','Eldritch Restoration',false,NULL,NULL,'d10',NULL,5,NULL,NULL,NULL),
	 ('e6261156-6f2a-41e6-af70-9cfdf289958d'::uuid,'01990b5c-6fd2-7f68-a950-3825e395dcc9'::uuid,'If the aboleth fails a saving throw, it can choose to succeed instead.','Legendary Resistance',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('f23bd878-9258-40f7-9a3d-b011b713cde9'::uuid,'01990b5c-77d9-7078-957f-8951783b2188'::uuid,'The abominable yeti makes two claw attacks.','Actions',false,NULL,NULL,'d6','Slashing',2,NULL,NULL,NULL),
	 ('2e9eea99-b60b-495b-a36d-4cc361a53788'::uuid,'01990b5c-aee7-7898-a2f6-48c3874a04d2'::uuid,'Amphibious. The dragon can breathe air and water.','Amphibious',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('6cbf5753-fec5-4791-a25b-99057911a9b3'::uuid,'01990b5c-aee7-7898-a2f6-48c3874a04d2'::uuid,'Legendary Resistance (3/Day, or 4/Day in Lair). If the dragon fails a saving throw, it can choose to succeed instead.','Legendary Resistance',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('2c043c25-2f89-4576-99c2-c77c2bc720d0'::uuid,'01990b5c-e19f-7df2-84c2-95757a34cecc'::uuid,'Legendary Resistance (3/Day, or 4/Day in Lair). If the dragon fails a saving throw, it can choose to succeed instead.','Legendary Resistance',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
