	 ('28615690-8340-46f4-b0b9-384ec484bf41'::uuid,'01990b7e-f212-77ac-9ca0-e7b03f007090'::uuid,'Tunneler. The ankheg can burrow through solid rock at half its Burrow Speed and leaves a 10-foot-diameter tunnel in its wake.','Tunneler',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('a1a6528c-c25e-4091-9ded-f05787e75e91'::uuid,'01990b7f-1735-7fd8-b23d-b3b3c164281d'::uuid,'The arcanaloth can use its Change Shape at will, polymorphing into a beast form or back into its true form.','Actions',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('a231cbb2-b93b-4ebd-8170-7d66b8eda798'::uuid,'01990b7f-22c0-7fea-8f48-014437294300'::uuid,'The arch-hag can take 3 legendary actions, choosing from the options below. Only one legendary action option can be used at a time and only at the end of another creature''s turn. The arch-hag regains spent legendary actions at the start of its turn.','Actions',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO public.traits (id,monster_id,description,title,is_optional,attack_bonus,damage_bonus,damage_dice,damage_type,number_damage_dice,advantage_condition,disadvantage_condition,trait_trigger) VALUES
	 ('8beae363-8dfa-40db-94cb-5b6e651fff09'::uuid,'01990b7f-3b42-75a8-adbb-a786a2106a4c'::uuid,'Amphibious. The archelon can breathe air and water.','Amphibious',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('fcad981d-4ed8-4912-b8aa-bcec82ad38ec'::uuid,'01990b7f-6041-7fe4-bcce-41ed203b0eb5'::uuid,'Magic Resistance. The archmage has Advantage on saving throws against spells and other magical effects.','Magic Resistance',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('0706d368-f7f8-46c9-adaf-1f0857d153c6'::uuid,'01990b7f-b32a-72f3-8697-6b09e2c1253f'::uuid,'Evasion. If the assassin is subjected to an effect that allows it to make a Dexterity saving throw to take only half damage, the assassin instead takes no damage if it succeeds on the save and only half damage if it fails. It can''t use this trait if it has the Incapacitated condition.','Evasion',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('04f54898-c4ba-4d8b-93ab-1045ac77420b'::uuid,'01990b7f-d452-70af-bddc-63cfdb18fc2b'::uuid,'The azer pyromancer makes two attacks with its fiery scimitar. Fiery Scimitar. Melee Weapon Attack: +5 to hit, reach 5 ft., one target. Hit: 7 (1d8 + 3) slashing damage plus 3 (1d6) fire damage.','Actions',false,5,3,'d8','Slashing',1,NULL,NULL,NULL),
	 ('04aa3e9d-3bd6-4fbe-a934-2c5fe31523c6'::uuid,'01990b7f-e95e-7fa0-92fa-a15e2e7c13f4'::uuid,'Illumination. The azer sheds Bright Light in a 10-foot radius and Dim Light for an additional 10 feet.','Illumination',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('f6595dba-212e-4714-84e1-43880132e550'::uuid,'01990b7f-e95e-7fa0-92fa-a15e2e7c13f4'::uuid,'Fire Aura. At the end of each of the azer''s turns, each creature of the azer''s choice in a 5-foot Emanation originating from the azer takes 5 (1d10) Fire damage unless the azer has the Incapacitated condition.','Fire Aura',false,NULL,NULL,'d10','Fire',1,NULL,NULL,NULL),
	 ('f936fed7-31f7-491a-a17c-705daa7b697e'::uuid,'01990b7f-fb4d-72ea-b12c-7ca4ef065e45'::uuid,'Pack Tactics. The baboon has Advantage on an attack roll against a creature if at least one of the baboon''s allies is within 5 feet of the creature and the ally doesn''t have the Incapacitated condition.','Pack Tactics',false,NULL,NULL,NULL,NULL,NULL,'if at least one of the baboon''s allies is within 5 feet of the creature and the ally doesn''t have the Incapacitated condition',NULL,NULL),
	 ('1232ba31-8ee6-4d14-a940-994fa3c573ae'::uuid,'01990b80-2cfa-7ed3-a8d5-c6aad63c171e'::uuid,'The balor explodes when it dies. Dexterity Saving Throw: DC 20, each creature in a 30-foot Emanation originating from the balor. Failure: 31 (9d6) Fire damage plus 31 (9d6) Force damage. Success: Half damage. Failure or Success: If the balor dies outside the Abyss, it gains a new body instantly, reviving with all its Hit Points somewhere in the Abyss.','Death Throes',false,NULL,NULL,'d6','Fire',9,NULL,NULL,NULL),
	 ('75148465-9e92-46dd-9df7-66ef01df9c1d'::uuid,'01990b80-2cfa-7ed3-a8d5-c6aad63c171e'::uuid,'At the end of each of the balor''s turns, each creature in a 5-foot Emanation originating from the balor takes 13 (3d8) Fire damage.','Fire Aura',false,NULL,NULL,'d8','Fire',3,NULL,NULL,NULL),
	 ('79c285b3-e6bc-4930-afee-39ae3d1913ef'::uuid,'01990b80-2cfa-7ed3-a8d5-c6aad63c171e'::uuid,'If the balor fails a saving throw, it can choose to succeed instead.','Legendary Resistance (3/Day)',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
