	 ('98abb6cf-8df9-44c3-bb46-ccc99e8400c9'::uuid,'01990b80-2cfa-7ed3-a8d5-c6aad63c171e'::uuid,'The balor has Advantage on saving throws against spells and other magical effects.','Magic Resistance',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('589d3185-1b2a-4fe9-9068-223ffd7b8475'::uuid,'01990b80-55a5-7750-8c94-616e99cc4266'::uuid,'The bandit crime lord makes two melee attacks.','Actions',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('78f588a1-68a9-4813-b350-574e0409a378'::uuid,'01990b80-600e-7e9a-82ff-20404d25cb3e'::uuid,'The banshee wails, the sound of which is harmful to all living creatures within 30 feet of the banshee. Each creature in that area must succeed on a DC 13 Constitution saving throw or take 14 (4d6) psychic damage and be frightened for 1 minute. A frightened target can repeat the saving throw at the end of each of its turns, ending the effect on itself on a success. If a target''s saving throw is successful or the effect ends for it, the target is immune to the banshee''s Wail for the next 24 hours.','Actions',false,NULL,NULL,'d6','Psychic',4,NULL,NULL,NULL),
	 ('58031dc6-4947-40b4-b4c4-20b55429be71'::uuid,'01990b80-8bc7-7fe9-9808-3b9fc06815b0'::uuid,'If the devil dies outside the Nine Hells, its body disappears in sulfurous smoke, and it gains a new body instantly, reviving with all its Hit Points somewhere in the Nine Hells.','Diabolical Restoration',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'If the devil dies outside the Nine Hells'),
	 ('642d23fd-2af8-44d6-94b7-aa07f66aa10a'::uuid,'01990b80-8bc7-7fe9-9808-3b9fc06815b0'::uuid,'At the start of each of its turns, the devil deals 5 (1d10) Piercing damage to any creature it is grappling or any creature grappling it.','Barbed Hide',false,NULL,NULL,'d10','Piercing',1,NULL,NULL,'At the start of each of its turns'),
	 ('7667384f-5a95-402e-8e86-4003c2781617'::uuid,'01990b80-8bc7-7fe9-9808-3b9fc06815b0'::uuid,'The devil has Advantage on saving throws against spells and other magical effects.','Magic Resistance',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('69435de8-306d-405c-a432-460a36941ce1'::uuid,'01990b80-9860-771a-ad80-1bb7012ef2e0'::uuid,'Ranged Weapon Attack: +7 to hit, range 30/60 ft., one target. Hit: 21 (3d8 + 8) bludgeoning damage.','Rock',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('be9762bb-d7bc-4298-8a29-4157d9f9844f'::uuid,'01990b80-9860-771a-ad80-1bb7012ef2e0'::uuid,'Melee Weapon Attack: +7 to hit, reach 5 ft., one target. Hit: 11 (2d6 + 4) bludgeoning damage.','Fist',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('d5208cb2-ace0-4083-8966-8a55bc56d95c'::uuid,'01990b80-9860-771a-ad80-1bb7012ef2e0'::uuid,'Melee Weapon Attack: +7 to hit, reach 5 ft., one target. Hit: 7 (1d6 + 4) piercing damage.','Bite',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('e813dda2-f539-4e4a-9852-3501c578f90f'::uuid,'01990b80-9860-771a-ad80-1bb7012ef2e0'::uuid,'The barlgura makes three attacks: one with its bite and two with its fists.','Multiattack',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
