	 ('3b3fbf81-ba9c-471f-b833-ac0c2deb474f'::uuid,'01990b81-3834-7351-a4b2-d0d4594d4ddd'::uuid,'Bloodied Frenzy. While Bloodied, the berserker has Advantage on attack rolls and saving throws.','Bloodied Frenzy',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'While Bloodied'),
	 ('94fea077-5f8e-4b2b-8b5d-604541dc8ee0'::uuid,'01990b81-5e6c-787c-bf13-6a2af60608ec'::uuid,'Amphibious. The dragon can breathe air and water.','Amphibious',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('3ffaa795-66c9-4236-a8b0-d0a0e424fb14'::uuid,'01990b81-7e06-74b1-b275-591731ca6231'::uuid,'A creature that hits the pudding with a melee attack roll takes 4 (1d8) Acid damage. Nonmagical ammunition is destroyed immediately after hitting the pudding and dealing any damage. Any nonmagical weapon takes a cumulative −1 penalty to attack rolls immediately after dealing damage to the pudding and coming into contact with it. The weapon is destroyed if the penalty reaches −5. The penalty can be removed by casting the Mending spell on the weapon. In 1 minute, the pudding can eat through 2 feet of nonmagical wood or metal.','Corrosive Form',false,NULL,NULL,'d8','Acid',1,NULL,NULL,NULL),
	 ('bc86d958-6a18-4416-aa56-626d00c87223'::uuid,'01990b81-7e06-74b1-b275-591731ca6231'::uuid,'The pudding can climb difficult surfaces, including along ceilings, without needing to make an ability check.','Spider Climb',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('d90e734f-4a69-4065-9fc9-f39a40062f7a'::uuid,'01990b81-7e06-74b1-b275-591731ca6231'::uuid,'The pudding can move through a space as narrow as 1 inch without expending extra movement to do so.','Amorphous',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('fcb61d6c-620a-4b31-a575-a980a044f53f'::uuid,'01990b81-b7b7-75d3-992f-3d3e3db3b941'::uuid,'Pack Tactics. The hawk has Advantage on an attack roll against a creature if at least one of the hawk''s allies is within 5 feet of the creature and the ally doesn''t have the Incapacitated condition.','Pack Tactics',false,NULL,NULL,NULL,NULL,NULL,'if at least one of the hawk''s allies is within 5 feet of the creature and the ally doesn''t have the Incapacitated condition',NULL,NULL),
	 ('2e0aea38-efac-4afb-8a85-7829d390394b'::uuid,'01990b88-aa7b-7878-91c3-24e32b50f8e9'::uuid,'The ettercap ignores movement restrictions caused by webs, and the ettercap knows the location of any other creature in contact with the same web.','Web Walker',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
