	 ('74da3a45-8dcf-4add-a01a-58f1c8ecd98f'::uuid,'01990b82-b1fe-7d5a-bf6c-402ce07b35c1'::uuid,'Abduct. The bugbear needn''t spend extra movement to move a creature it is grappling.','Abduct',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('b1b43c09-920d-4406-b0b6-394714c0c064'::uuid,'01990b82-c7d6-7162-a5b7-480ec0195fa1'::uuid,'Abduct. The bugbear needn''t spend extra movement to move a creature it is grappling.','Abduct',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('0cde77d4-c45f-4efa-80cc-18ed9b987a22'::uuid,'01990b83-0353-7b20-9d38-01e134faa474'::uuid,'Speak with Frogs and Toads. The bullywug can communicate simple concepts to frogs and toads when it speaks in Bullywug.','Speak with Frogs and Toads',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('d566c8a9-9d08-43c7-aaba-7c677c71cf70'::uuid,'01990b83-0353-7b20-9d38-01e134faa474'::uuid,'Amphibious. The bullywug can breathe air and water.','Amphibious',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
