	 ('1463da7f-e7ca-4321-9d67-13325953fecc'::uuid,'01990b83-a488-7fca-a5dc-87c3fd0c8b43'::uuid,'The devil has Advantage on saving throws against spells and other magical effects.','Magic Resistance',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
