INSERT INTO public.traits (id,monster_id,description,title,is_optional,attack_bonus,damage_bonus,damage_dice,damage_type,number_damage_dice,advantage_condition,disadvantage_condition,trait_trigger) VALUES
	 ('801933bd-5160-4828-9e10-70734624c6b8'::uuid,'01990b84-11da-783f-8008-0d2a54a2f35f'::uuid,'Whenever the golem starts its turn Bloodied, roll 1d6. On a 6, the golem goes berserk. On each of its turns while berserk, the golem attacks the nearest creature it can see. If no creature is near enough to move to and attack, the golem attacks an object. Once the golem goes berserk, it continues to be berserk until it is destroyed or it is no longer Bloodied.','Berserk',false,NULL,NULL,'d6',NULL,1,NULL,NULL,'Whenever the golem starts its turn Bloodied'),
	 ('b795b147-ebef-4470-b881-f33f5535920b'::uuid,'01990b84-11da-783f-8008-0d2a54a2f35f'::uuid,'The golem can''t shape-shift.','Immutable Form',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('ba66119d-945a-4d30-9ed3-725c736e5ff5'::uuid,'01990b84-11da-783f-8008-0d2a54a2f35f'::uuid,'Whenever the golem is subjected to Acid damage, it takes no damage and instead regains a number of Hit Points equal to the Acid damage dealt.','Acid Absorption',false,NULL,NULL,NULL,'Acid',NULL,NULL,NULL,NULL),
	 ('7c9a1b59-4637-4e93-88f0-80ba1b935962'::uuid,'01990b84-4e29-7bd4-a153-266dabb756b2'::uuid,'Light Sensitivity. While in Bright Light, the cloaker has Disadvantage on attack rolls.','Light Sensitivity',false,NULL,NULL,NULL,NULL,NULL,NULL,'While in Bright Light',NULL),
	 ('6f425c92-3517-480a-81df-df5970922def'::uuid,'01990b84-8af1-7627-b127-99b9fc6112fc'::uuid,'The Cockatrice Regent can take 3 actions: Multiattack, Petrifying Gaze, and Bite.','Actions',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('38b5a730-8f0f-43c9-b483-a179ba0acd24'::uuid,'01990b84-97b2-79c3-a633-b9d100100239'::uuid,'The Colossus can make two slam attacks. It can also use its Thunderous Roar.','Actions',false,NULL,NULL,'d8','Bludgeoning',2,NULL,NULL,NULL),
	 ('bb19d0db-e306-4d4e-bada-2b1b34758034'::uuid,'01990b84-a6be-7413-a6de-e6cd8a77693a'::uuid,'Training. The commoner has proficiency in one skill of the DM''s choice and has Advantage whenever it makes an ability check using that skill.','Training',false,NULL,NULL,NULL,NULL,NULL,'whenever it makes an ability check using that skill',NULL,NULL),
	 ('0f4df0e1-d2e4-480a-8b89-e2503c5fb888'::uuid,'01990b84-e8d3-7a19-905f-f794fd139b8d'::uuid,'Shielded Mind. The couatl''s thoughts can''t be read by any means, and other creatures can communicate with it telepathically only if it allows them.','Shielded Mind',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('12ed5a11-c7c0-4dc6-9799-10b62d9843f3'::uuid,'01990b84-f750-704b-b607-e7db69ae8bfa'::uuid,'Amphibious. The crab can breathe air and water.','Amphibious',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('8deedf48-a87d-4842-8289-8718973e90cb'::uuid,'01990b85-1c56-7205-85c3-47035b70aed4'::uuid,'Hold Breath. The crocodile can hold its breath for 1 hour.','Hold Breath',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
