	 ('a44cd3a3-cc0d-49d3-9c6a-295b76751dfd'::uuid,'01990b85-4cbc-73a1-890d-635e85323d75'::uuid,'The dao makes two attacks with its maul.','Actions',false,NULL,NULL,'d6','Bludgeoning',2,NULL,NULL,NULL),
	 ('ed25460d-a026-421f-97c2-1effbf44a600'::uuid,'01990b85-a23a-742b-93b1-a508bcaebc22'::uuid,'The death knight aspirant makes two melee attacks.','Actions',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('f18adce1-251c-48c0-92d7-dae14394c725'::uuid,'01990b85-b46f-7994-9f67-63c2e9d965ce'::uuid,'The death tyrant can take 3 legendary actions, choosing from the options below. Only one legendary action option can be used at a time and only at the end of another creature''s turn. The death tyrant regains spent legendary actions at the start of its turn.','Actions',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('63dd384e-f483-4fdc-a481-e7fde5d0da17'::uuid,'01990b85-c435-7d99-9eae-82cbfc6fc221'::uuid,'Agile. The deer doesn''t provoke an Opportunity Attack when it moves out of an enemy''s reach.','Agile',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('bf1ca551-0d92-428c-be32-8245b1c6b5ff'::uuid,'01990b85-d00a-72af-b30c-bff27584b0ad'::uuid,'The demilich can take 3 legendary actions, choosing from the options below. Only one legendary action option can be used at a time and only at the end of another creature''s turn. The demilich regains spent legendary actions at the start of its turn. Cantrip. The demilich casts a cantrip. Paralyzing Touch (Costs 2 Actions). The demilich uses its Paralyzing Touch. Energy Drain (Costs 3 Actions). The demilich uses its Energy Drain.','Actions',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('16689375-60e3-4f48-9b65-9ecb901216b6'::uuid,'01990b85-f49c-72ad-b0ae-1763b0203178'::uuid,'Exalted Restoration. If the deva dies outside Mount Celestia, its body disappears, and it gains a new body instantly, reviving with all its Hit Points somewhere in Mount Celestia.','Exalted Restoration',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('75db58f0-5c48-451e-ad83-5f5f863abed0'::uuid,'01990b85-f49c-72ad-b0ae-1763b0203178'::uuid,'Magic Resistance. The deva has Advantage on saving throws against spells and other magical effects.','Magic Resistance',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('07c8d947-4379-4283-933d-17a83948dabb'::uuid,'01990b86-05c3-7455-ac1c-9c646a8d4bec'::uuid,'Pack Tactics. The wolf has Advantage on an attack roll against a creature if at least one of the wolf''s allies is within 5 feet of the creature and the ally doesn''t have the Incapacitated condition.','Pack Tactics',false,NULL,NULL,NULL,NULL,NULL,'if at least one of the wolf''s allies is within 5 feet of the creature and the ally doesn''t have the Incapacitated condition',NULL,NULL),
	 ('a1a0f07c-c644-4a13-9d4b-bf65c5ad5c4f'::uuid,'01990b86-24c4-7135-b0fb-44bba7d015fe'::uuid,'If the displacer beast is subjected to an effect that allows it to make a saving throw to take only half damage, it instead takes no damage if it succeeds on the save and half damage if it fails. It can''t use this trait if it has the Incapacitated condition.','Avoidance',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('a2dae513-3f4e-4027-928e-15a78a7f65be'::uuid,'01990b86-24c4-7135-b0fb-44bba7d015fe'::uuid,'Attack rolls against the displacer beast have Disadvantage, since it projects an illusion that makes it appear to be near its actual location. This trait is suppressed while the displacer beast has the Incapacitated condition.','Displacement',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO public.traits (id,monster_id,description,title,is_optional,attack_bonus,damage_bonus,damage_dice,damage_type,number_damage_dice,advantage_condition,disadvantage_condition,trait_trigger) VALUES
	 ('17d26c0a-2552-4177-830c-910ad48083d5'::uuid,'01990b86-4a7a-785c-b525-bc7cb0a0ffab'::uuid,'The djinni has a 30 percent chance of knowing the Wish spell. If the djinni knows it, the djinni can cast it only on behalf of a non-genie creature who communicates a wish in a way the djinni can understand. If the djinni casts the spell for the creature, the djinni suffers none of the spell''s stress. Once the djinni has cast it three times, the djinni can''t do so again for 365 days.','Wishes',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('3ad52038-9edc-4970-8e04-63267651ac3b'::uuid,'01990b86-4a7a-785c-b525-bc7cb0a0ffab'::uuid,'If the djinni dies outside the Elemental Plane of Air, its body dissolves into mist, and it gains a new body in 1d4 days, reviving with all its Hit Points somewhere on the Plane of Air.','Elemental Restoration',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('4eda416e-e5b1-47d8-aca5-d8411e8dab7c'::uuid,'01990b86-4a7a-785c-b525-bc7cb0a0ffab'::uuid,'The djinni has Advantage on saving throws against spells and other magical effects.','Magic Resistance',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('40957e5f-64f6-421c-94be-374bb1b13822'::uuid,'01990b86-b0d4-7af4-b836-77c7e901c288'::uuid,'Soul Gem. The dracolich has a magical gem. If the dracolich is destroyed while the gem is on the same plane of existence as it, the dracolich gains a new body in 1d20 days, regaining all its Hit Points and appearing within 5 feet of the gem. The gem is a Tiny object that has AC 20; HP 50; and Immunity to Necrotic, Poison, and Psychic damage. The gem regains all its Hit Points at the end of every turn, but it turns to dust if reduced to 0 Hit Points. If the gem is destroyed, the dracolich can create a new one by completing an 8-hour ritual using a gem worth 1,000+ GP and by expending 5,000 GP, which the ritual consumes.','Soul Gem',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('85979036-bf2f-4ead-bdb8-4611ab0951eb'::uuid,'01990b86-b0d4-7af4-b836-77c7e901c288'::uuid,'Life Suppression. Creatures within 60 feet of the dracolich can''t regain Hit Points.','Life Suppression',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('8cea59f7-0449-42a0-8ff4-215e88bfacc3'::uuid,'01990b86-b0d4-7af4-b836-77c7e901c288'::uuid,'Magic Resistance. The dracolich has Advantage on saving throws against spells and other magical effects.','Magic Resistance',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('c967ddf1-8c8f-40d3-9bd5-4940924633a0'::uuid,'01990b86-b0d4-7af4-b836-77c7e901c288'::uuid,'Legendary Resistance (3/Day, or 4/Day in Lair). If the dracolich fails a saving throw, it can choose to succeed instead.','Legendary Resistance',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('6064e2a0-9b23-40d8-96d0-b9fd5b24e291'::uuid,'01990b86-d580-7cac-ad52-cb96572ae4c7'::uuid,'Amphibious. The dragon can breathe air and water.','Amphibious',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('2905469a-fd42-41c8-bc33-9b9e412d39e8'::uuid,'01990b87-0835-7ab6-b720-c36feed0a1b6'::uuid,'The drider ignores movement restrictions caused by webs, and the drider knows the location of any other creature in contact with the same web.','Web Walker',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('30ad8434-317c-4be8-b47f-8c33a25aad80'::uuid,'01990b87-0835-7ab6-b720-c36feed0a1b6'::uuid,'The drider can climb difficult surfaces, including along ceilings, without needing to make an ability check.','Spider Climb',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
