	 ('13947665-8e55-4da1-bc29-8d8835e90e07'::uuid,'01990b87-4af2-7c1c-84bf-6484a78b1613'::uuid,'Speak with Beasts and Plants. The dryad can communicate with Beasts and Plants as if they shared a language.','Speak with Beasts and Plants',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
