	 ('82073243-0341-41fd-957d-2347c73a279b'::uuid,'01990b87-8e0b-7f19-ad80-21a95b744504'::uuid,'Siege Monster. The elemental deals double damage to objects and structures.','Siege Monster',false,NULL,2,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('146148ce-9443-46e3-a2e8-b3620ed85f20'::uuid,'01990b87-b9cc-7d5f-b567-769c5919692e'::uuid,'The efreeti has Advantage on saving throws against spells and other magical effects.','Magic Resistance',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('541a1e06-079e-40ea-8862-4e7e944787e1'::uuid,'01990b87-b9cc-7d5f-b567-769c5919692e'::uuid,'If the efreeti dies outside the Elemental Plane of Fire, its body dissolves into ash, and it gains a new body in 1d4 days, reviving with all its Hit Points somewhere on the Plane of Fire.','Elemental Restoration',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('966ccad8-b4be-43b4-a4a6-e947e9b77ce3'::uuid,'01990b87-b9cc-7d5f-b567-769c5919692e'::uuid,'The efreeti has a 30 percent chance of knowing the Wish spell. If the efreeti knows it, the efreeti can cast it only on behalf of a non-genie creature who communicates a wish in a way the efreeti can understand. If the efreeti casts the spell for the creature, the efreeti suffers none of the spell''s stress. Once the efreeti has cast it three times, the efreeti can''t do so again for 365 days.','Wishes',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('1e96429c-3a6d-4044-baca-76a1ad2de34a'::uuid,'01990b87-c81d-7590-ac33-7f246ae31afa'::uuid,'The Elemental Cataclysm can take 3 actions: Multiattack, Elemental Burst, Earthquake.','Actions',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO public.traits (id,monster_id,description,title,is_optional,attack_bonus,damage_bonus,damage_dice,damage_type,number_damage_dice,advantage_condition,disadvantage_condition,trait_trigger) VALUES
	 ('1d959c68-facd-4ab0-a4a3-5bd8d7e3ad33'::uuid,'01990b88-3b22-7f80-9ecd-18b80e07b3dd'::uuid,'Legendary Resistance (4/Day). If the empyrean fails a saving throw, it can choose to succeed instead.','Legendary Resistance',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('9d5af1f1-4c60-4d72-96d8-f1830d7b7de0'::uuid,'01990b88-3b22-7f80-9ecd-18b80e07b3dd'::uuid,'Magic Resistance. The empyrean has Advantage on saving throws against spells and other magical effects.','Magic Resistance',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('78d0ce91-59f0-4033-90c2-934c12e41838'::uuid,'01990b88-5c57-7d6c-ab15-6ca99e6111fa'::uuid,'Incorporeal Movement. The empyrean can move through other creatures and objects as if they were Difficult Terrain. It takes 5 (1d10) Force damage if it ends its turn inside an object.','Incorporeal Movement',false,NULL,NULL,'d10','Force',1,NULL,NULL,'if it ends its turn inside an object'),
	 ('c609450e-78d5-4f5c-8ce8-1c27c32d31a8'::uuid,'01990b88-5c57-7d6c-ab15-6ca99e6111fa'::uuid,'Magic Resistance. The empyrean has Advantage on saving throws against spells and other magical effects.','Magic Resistance',false,NULL,NULL,NULL,NULL,NULL,'on saving throws against spells and other magical effects',NULL,NULL),
	 ('0b5c5980-95f2-4a3c-8b00-da14337cbb75'::uuid,'01990b88-8404-7707-8fe6-ed71698b280e'::uuid,'If the erinyes dies outside the Nine Hells, its body disappears in sulfurous smoke, and it gains a new body instantly, reviving with all its Hit Points somewhere in the Nine Hells.','Diabolical Restoration',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('5f58034b-c585-461e-b48c-3e7a6ed409c9'::uuid,'01990b88-8404-7707-8fe6-ed71698b280e'::uuid,'The erinyes has Advantage on saving throws against spells and other magical effects.','Magic Resistance',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('bdbbb76d-cee0-49b2-b24e-427504952a8a'::uuid,'01990b88-8404-7707-8fe6-ed71698b280e'::uuid,'The erinyes has a magic rope. While bearing it, the erinyes can use the Entangling Rope action. The rope has AC 20, HP 90, and Immunity to Poison and Psychic damage. The rope turns to dust if reduced to 0 Hit Points, if it is 5+ feet away from the erinyes for 1 hour or more, or if the erinyes dies. If the rope is damaged or destroyed, the erinyes can fully restore it when finishing a Short or Long Rest.','Magic Rope',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('fdd38c82-dd2d-4691-8280-f109aa00f61f'::uuid,'01990b88-aa7b-7878-91c3-24e32b50f8e9'::uuid,'The ettercap can climb difficult surfaces, including along ceilings, without needing to make an ability check.','Spider Climb',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('cee30ccc-9666-46ed-a927-61c0b9243455'::uuid,'01990b88-c6ec-7810-81f1-9e125bb7324f'::uuid,'The adult faerie dragon can use its Change Color and Confusion Breath. It can use its spells, and it makes three attacks: one with its bite and two with its claws.','Actions',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('382b7f56-d619-4aee-ae3d-06474f00b31a'::uuid,'01990b88-ce46-735f-9e5b-f2f222ce4299'::uuid,'The Faerie Dragon Youth can use its Color Spray.','Actions',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO public.traits (id,monster_id,description,title,is_optional,attack_bonus,damage_bonus,damage_dice,damage_type,number_damage_dice,advantage_condition,disadvantage_condition,trait_trigger) VALUES
	 ('866521f2-f2b3-45b2-a330-0c73b430565e'::uuid,'01990b89-0b5c-7bff-8495-099b3ceb1e8a'::uuid,'The elemental takes 3 (1d6) Cold damage for every 5 feet the elemental moves in water or for every gallon of water splashed on it.','Water Susceptibility',false,NULL,NULL,'d6','Cold',1,NULL,NULL,NULL),
	 ('8b88ccb6-20d3-43a3-9ab5-c3a1cf0be81d'::uuid,'01990b89-0b5c-7bff-8495-099b3ceb1e8a'::uuid,'The elemental sheds Bright Light in a 30-foot radius and Dim Light for an additional 30 feet.','Illumination',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('8f58ddda-e4aa-46b0-97f0-14170e55cb88'::uuid,'01990b89-0b5c-7bff-8495-099b3ceb1e8a'::uuid,'The elemental can move through a space as narrow as 1 inch wide without expending extra movement to do so, and it can enter a creature''s space and stop there. The first time it enters a creature''s space on a turn, that creature takes 5 (1d10) Fire damage.','Fire Form',false,NULL,NULL,'d10','Fire',1,NULL,NULL,NULL),
	 ('c4640aae-237b-4c30-8787-3eb63fc4154b'::uuid,'01990b89-0b5c-7bff-8495-099b3ceb1e8a'::uuid,'At the end of each of the elemental''s turns, each creature in a 10-foot Emanation originating from the elemental takes 5 (1d10) Fire damage. Creatures and flammable objects in the Emanation start burning.','Fiery Aura',false,NULL,NULL,'d10','Fire',1,NULL,NULL,NULL),
	 ('b8b09e76-7526-4bb2-8d92-93ea2c3f0900'::uuid,'01990b89-29a6-7954-bfdd-8dffd6d1705e'::uuid,'The flameskull can take 3 legendary actions, choosing from the options below. Only one legendary action option can be used at a time and only at the end of another creature''s turn. The flameskull regains spent legendary actions at the start of its turn. Fire Ray. The flameskull casts fireball. It can then use a bonus action, moving up to its speed before or after casting the spell. Paralyzing Touch. The flameskull uses its Paralyzing Touch. Spell. The flameskull casts a spell.','Actions',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('04477b94-2e88-4dd4-a9f1-7e7301a7aa27'::uuid,'01990b89-4e73-72ac-aa87-ff8511543a7b'::uuid,'The skeleton explodes when it dies. Dexterity Saving Throw: DC 12, each creature in a 10-foot Emanation originating from the skeleton. Failure: 14 (4d6) Fire damage. Success: Half damage.','Death Burst',false,NULL,NULL,'d6','Fire',4,NULL,NULL,'when it dies'),
	 ('9be7ccd8-e690-48cb-8a00-abd28d8d5b4a'::uuid,'01990b89-4e73-72ac-aa87-ff8511543a7b'::uuid,'The skeleton sheds Bright Light in a 15-foot radius and Dim Light for an additional 15 feet.','Illumination',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('14a5526f-9ca0-4ab0-a2bd-28d4bff486aa'::uuid,'01990b89-7002-7e74-ba06-44c5687a3ddd'::uuid,'Whenever the golem starts its turn Bloodied, roll 1d6. On a 6, the golem goes berserk. On each of its turns while berserk, the golem attacks the nearest creature it can see. If no creature is near enough to move to and attack, the golem attacks an object. Once the golem goes berserk, it remains so until it is destroyed or it is no longer Bloodied. The golem''s creator, if within 60 feet of the berserk golem, can try to calm it by taking an action to make a DC 15 Charisma (Persuasion) check; the golem must be able to hear its creator. If this check succeeds, the golem ceases being berserk until the start of its next turn, at which point it resumes rolling for the Berserk trait again if it is still Bloodied.','Berserk',false,NULL,NULL,'d6',NULL,1,NULL,NULL,'Whenever the golem starts its turn Bloodied'),
	 ('42c4b038-3d1e-4324-9fba-595c695ed8b4'::uuid,'01990b89-7002-7e74-ba06-44c5687a3ddd'::uuid,'The golem can''t shape-shift.','Immutable Form',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('66f46adc-0744-457b-8fa6-74c2250efef8'::uuid,'01990b89-7002-7e74-ba06-44c5687a3ddd'::uuid,'If the golem takes Fire damage, it has Disadvantage on attack rolls and ability checks until the end of its next turn.','Aversion to Fire',false,NULL,NULL,NULL,'Fire',NULL,NULL,NULL,NULL);
INSERT INTO public.traits (id,monster_id,description,title,is_optional,attack_bonus,damage_bonus,damage_dice,damage_type,number_damage_dice,advantage_condition,disadvantage_condition,trait_trigger) VALUES
	 ('d51787d2-d4e5-4184-bd46-565d13ad2783'::uuid,'01990b89-7002-7e74-ba06-44c5687a3ddd'::uuid,'Whenever the golem is subjected to Lightning damage, it regains a number of Hit Points equal to the Lightning damage dealt.','Lightning Absorption',false,NULL,NULL,NULL,'Lightning',NULL,NULL,NULL,NULL),
	 ('ed459730-4d25-41cf-9bdc-31e7eac316f0'::uuid,'01990b89-7002-7e74-ba06-44c5687a3ddd'::uuid,'The golem has Advantage on saving throws against spells and other magical effects.','Magic Resistance',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('5e3e98be-ede7-4f5a-bdc6-fff8d899507d'::uuid,'01990b89-905c-7d0e-bf9b-a16b8172a90b'::uuid,'Prone Deficiency. If the flumph receives the Prone condition, roll a die. On an odd number, it has the Incapacitated condition. At the end of each of its turns, the flumph makes a DC 10 Dexterity saving throw, ending the Incapacitated condition on a success.','Prone Deficiency',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('6ed11c4e-5c12-48eb-b930-966d3ea6be65'::uuid,'01990b89-905c-7d0e-bf9b-a16b8172a90b'::uuid,'Telepathic Shroud. The flumph''s thoughts can''t be read by any means, and magic can''t detect its location or observe it remotely.','Telepathic Shroud',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('cba50c98-8a41-4aff-91d8-118826bb6466'::uuid,'01990b89-905c-7d0e-bf9b-a16b8172a90b'::uuid,'Advanced Telepathy. The flumph perceives the content of any telepathic communication within 60 feet of it.','Advanced Telepathy',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('bd417422-af5c-45bb-aabe-6f4b24ebfe14'::uuid,'01990b89-9e14-7a98-9021-d30e64a024d3'::uuid,'Flyby. The snake doesn''t provoke an Opportunity Attack when it flies out of an enemy''s reach.','Flyby',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('33d3e88e-3909-4616-82ae-650711bc8d7d'::uuid,'01990b89-afcc-7f8b-bffd-68c0b2bbd4fd'::uuid,'Amphibious. The frog can breathe air and water.','Amphibious',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('f7d6ac6e-fe6d-4b99-b26a-e1b6a3bbb553'::uuid,'01990b89-afcc-7f8b-bffd-68c0b2bbd4fd'::uuid,'Standing Leap. The frog''s Long Jump is up to 10 feet and its High Jump is up to 5 feet with or without a running start.','Standing Leap',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('efa93c2e-04ee-42f1-8fab-55772e327b34'::uuid,'01990b89-e1e8-7d85-a572-f717ecbf551e'::uuid,'Flyby. The gargoyle doesn''t provoke an Opportunity Attack when it flies out of an enemy''s reach.','Flyby',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('deca20fa-9684-488f-a53d-21d2f6cf4ee8'::uuid,'01990b89-f05c-701a-beaf-f22b1bb73f3f'::uuid,'Actions. Explosion. When a creature moves within 5 feet of the gas spore, it explodes in a 20-foot-radius sphere. Each creature in that area must succeed on a DC 15 Constitution saving throw or take 10 (3d6) poison damage and become infected with a disease that causes deathcap spores to sprout on the creature''s body. The creature must repeat the saving throw at the start of each of its turns. On a successful save, the disease ends on the creature. On a failed save, the creature''s body erupts in a cloud of spores, and the creature dies. The creature can be restored to life only by a greater restoration spell or similar magic.','Actions',false,NULL,NULL,'d6','Poison',3,NULL,NULL,'When a creature moves within 5 feet of the gas spore');
INSERT INTO public.traits (id,monster_id,description,title,is_optional,attack_bonus,damage_bonus,damage_dice,damage_type,number_damage_dice,advantage_condition,disadvantage_condition,trait_trigger) VALUES
	 ('164f1a14-49ba-4a4e-8556-8528f0d9215a'::uuid,'01990b8a-0abd-725b-835e-43eefe91db05'::uuid,'The cube fills its entire space and is transparent. Other creatures can enter that space, but a creature that does so is subjected to the cube''s Engulf and has Disadvantage on the saving throw. Creatures inside the cube have Total Cover, and the cube can hold one Large creature or up to four Medium or Small creatures inside itself at a time. As an action, a creature within 5 feet of the cube can pull a creature or an object out of the cube by succeeding on a DC 12 Strength (Athletics) check, and the puller takes 10 (3d6) Acid damage.','Ooze Cube',false,NULL,NULL,'d6','Acid',3,NULL,'on the saving throw','Engulf'),
	 ('5341d7ff-3fa1-4fb8-b846-e2694c2a5aad'::uuid,'01990b8a-0abd-725b-835e-43eefe91db05'::uuid,'Even when the cube is in plain sight, a creature must succeed on a DC 15 Wisdom (Perception) check to notice the cube if the creature hasn''t witnessed the cube move or otherwise act.','Transparent',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('9a8eb3fa-853a-4573-8370-393f68e4a4fa'::uuid,'01990b8a-25f7-7f90-82ef-56c581b854da'::uuid,'Stench. Constitution Saving Throw: DC 10, any creature that starts its turn in a 5-foot Emanation originating from the ghast. Failure: The target has the Poisoned condition until the start of its next turn. Success: The target is immune to this ghast''s Stench for 24 hours.','Stench',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'any creature that starts its turn in a 5-foot Emanation originating from the ghast'),
	 ('ff56c31a-b6e4-4f1f-b833-f12ea76c36a9'::uuid,'01990b8e-595e-7c24-b57f-98f71a97da4a'::uuid,'Amphibious. The hag can breathe air and water.','Amphibious',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('ecbe4444-2aa5-49c7-b0f0-a6efe26e6fe3'::uuid,'01990b8e-6790-7fc4-b1a1-6c232b55350c'::uuid,'The grell makes two attacks: one with its tentacles and one with its beak.','Actions',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('1444fde8-a8a7-4bd9-935a-579bcda48222'::uuid,'01990b8a-5613-7d52-980e-7b704db2fa2a'::uuid,'Incorporeal Movement. The ghost can move through other creatures and objects as if they were Difficult Terrain. It takes 5 (1d10) Force damage if it ends its turn inside an object.','Incorporeal Movement',false,NULL,NULL,'d10','Force',1,NULL,NULL,NULL),
	 ('f7704647-3dc9-4f6e-be2b-8529da7933b1'::uuid,'01990b8a-5613-7d52-980e-7b704db2fa2a'::uuid,'Ethereal Sight. The ghost can see 60 feet into the Ethereal Plane when it is on the Material Plane.','Ethereal Sight',false,NULL,NULL,NULL,'Force',NULL,NULL,NULL,NULL),
	 ('d2f72ed5-4f89-4abc-ba2d-a0d464cadb15'::uuid,'01990b8a-b210-78bb-bae8-1c38b3fba28e'::uuid,'Bloodied Fury. The boar has Advantage on melee attack rolls while it is Bloodied.','Bloodied Fury',false,NULL,NULL,NULL,NULL,NULL,'while it is Bloodied',NULL,NULL),
	 ('107126f1-2684-44d5-a9f5-9b770986d245'::uuid,'01990b8a-e16f-7168-b140-c7efc3359d3b'::uuid,'Amphibious. The crab can breathe air and water.','Amphibious',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('6a1eb87d-3b32-40ad-94ef-0516530205f2'::uuid,'01990b8a-f967-7355-b0f1-3d3afd0d9d5d'::uuid,'Hold Breath. The crocodile can hold its breath for 1 hour.','Hold Breath',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
