	 ('7a735355-ec5c-4cfb-b5f5-9d0003cca9f9'::uuid,'01990b8b-2ced-79cb-ae4a-ef2b82e713db'::uuid,'Illumination. The beetle sheds Bright Light in a 10-foot radius and Dim Light for an additional 10 feet.','Illumination',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('3627f74b-acca-439b-9bba-efd677ba6c35'::uuid,'01990b8b-51c4-7e64-a091-e018d08d0b1e'::uuid,'Amphibious. The frog can breathe air and water.','Amphibious',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('9479f2fa-17d6-4205-852e-3453ad9d9077'::uuid,'01990b8b-51c4-7e64-a091-e018d08d0b1e'::uuid,'Standing Leap. The frog''s Long Jump is up to 20 feet and its High Jump is up to 10 feet with or without a running start.','Standing Leap',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('d03f3353-8c0c-4f6d-9bdc-c18343dfdc22'::uuid,'01990b8b-7739-7ab9-81c0-8544d5f95137'::uuid,'The lizard can climb difficult surfaces, including along ceilings, without needing to make an ability check.','Spider Climb',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('3d661f4b-76d5-4354-b049-3f8c6aecd7d9'::uuid,'01990b8b-901f-7c6c-b9c1-81c82f45aeaa'::uuid,'Water Breathing. The octopus can breathe only underwater. It can hold its breath for 1 hour outside water.','Water Breathing',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('1dcdfb20-2dce-4e82-8300-5bbccd7af8f9'::uuid,'01990b8b-aaa9-7731-bbdf-5536ecc06363'::uuid,'Flyby. The owl doesn''t provoke an Opportunity Attack when it flies out of an enemy''s reach.','Flyby',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('d15da194-f7a5-45e7-bc64-63242974579b'::uuid,'01990b8b-be83-7e61-84be-ac62ebdc70c4'::uuid,'Pack Tactics. The rat has Advantage on an attack roll against a creature if at least one of the rat''s allies is within 5 feet of the creature and the ally doesn''t have the Incapacitated condition.','Pack Tactics',false,NULL,NULL,NULL,NULL,NULL,'if at least one of the rat''s allies is within 5 feet of the creature and the ally doesn''t have the Incapacitated condition',NULL,NULL),
	 ('da82c486-98bd-403c-b538-94a8ac1e51ff'::uuid,'01990b8c-0720-7c91-a79a-0ee072be9cab'::uuid,'Water Breathing. The seahorse can breathe only underwater.','Water Breathing',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('39f9eb7c-6910-45fa-a4bc-4060f5bd91c7'::uuid,'01990b8c-1a79-70d9-8b44-9ccb1bb8fd2c'::uuid,'Water Breathing. The shark can breathe only underwater.','Water Breathing',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('25ca9d8c-b010-478e-a3f9-8401c400a817'::uuid,'01990b8c-2f60-70e1-b4ff-998cc2f10495'::uuid,'The spider ignores movement restrictions caused by webs, and it knows the location of any other creature in contact with the same web.','Web Walker',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
