	 ('f17590e0-5fc4-4f38-ac18-e341983e072f'::uuid,'01990b8c-2f60-70e1-b4ff-998cc2f10495'::uuid,'The spider can climb difficult surfaces, including along ceilings, without needing to make an ability check.','Spider Climb',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('fcfcbd14-0d2d-4f75-979f-692217e2826c'::uuid,'01990b8c-5715-76de-b2d5-89d34398f6ba'::uuid,'Water Breathing. The squid can breathe only underwater.','Water Breathing',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('0277a9e9-1d51-4834-9b31-556af610b338'::uuid,'01990b8c-7a44-7a0e-97ba-f9010e75710c'::uuid,'Amphibious. The toad can breathe air and water.','Amphibious',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('cb756a38-1402-482b-9891-69fed6b3b5aa'::uuid,'01990b8c-7a44-7a0e-97ba-f9010e75710c'::uuid,'Standing Leap. The toad''s Long Jump is up to 20 feet and its High Jump is up to 10 feet with or without a running start.','Standing Leap',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('3dfa9e1e-2ad7-46aa-bee5-ae59807056f3'::uuid,'01990b8c-9651-77ef-b152-5df758ff38b7'::uuid,'Pack Tactics. The vulture has Advantage on an attack roll against a creature if at least one of the vulture''s allies is within 5 feet of the creature and the ally doesn''t have the Incapacitated condition.','Pack Tactics',false,NULL,NULL,NULL,NULL,NULL,'if at least one of the vulture''s allies is within 5 feet of the creature and the ally doesn''t have the Incapacitated condition',NULL,NULL),
	 ('0b97ea3b-0511-4b9c-94a5-ce81bd24a046'::uuid,'01990b8c-a74e-70c0-926d-1099ff063e14'::uuid,'Flyby. The wasp doesn''t provoke an Opportunity Attack when it flies out of an enemy''s reach.','Flyby',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('c7a489fa-8731-4cd7-9298-1aba5f79415a'::uuid,'01990b8c-bf84-712f-8454-f0680352d835'::uuid,'The spider can climb difficult surfaces, including along ceilings, without needing to make an ability check.','Spider Climb',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('4f6f2486-e430-401e-8273-9d0ae9d69f67'::uuid,'01990b8c-df73-7037-ab0d-ec4f3bd90684'::uuid,'Aberrant Ground. The ground in a 10-foot Emanation originating from the mouther is Difficult Terrain.','Aberrant Ground',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('cf9200ff-1b23-498a-931f-afda45ea26ab'::uuid,'01990b8c-df73-7037-ab0d-ec4f3bd90684'::uuid,'Gibbering. The mouther babbles incoherently while it doesn''t have the Incapacitated condition. Wisdom Saving Throw: DC 10, any creature that starts its turn within 20 feet of the mouther while it is babbling. Failure: The target rolls 1d8 to determine what it does during the current turn:
INSERT INTO public.traits (id,monster_id,description,title,is_optional,attack_bonus,damage_bonus,damage_dice,damage_type,number_damage_dice,advantage_condition,disadvantage_condition,trait_trigger) VALUES
	 ('775c1be6-9538-4fbd-913d-1a1bfb450145'::uuid,'01990b8d-1930-7da2-acf1-a57bd76f452c'::uuid,'Magic Resistance. The glabrezu has Advantage on saving throws against spells and other magical effects.','Magic Resistance',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('6977a9fe-81f2-49b3-bea3-19a22ccce811'::uuid,'01990b8d-d975-7b5c-9783-57cd638e5f74'::uuid,'Amphibious. The dragon can breathe air and water.','Amphibious',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('782686b2-fac4-4dd6-8ed5-81b9ff250fdb'::uuid,'01990b8e-06e6-76cf-8783-5dcb254f41d6'::uuid,'The graveyard revenant makes two attacks with its grave-encrusted claws. Melee Weapon Attack: +6 to hit, reach 5 ft., one target. Hit: 13 (2d8 + 4) slashing damage. If the target is a creature, it must succeed on a DC 14 Constitution saving throw or be cursed with a revenant''s curse. The cursed target can''t regain hit points, and its hit point maximum decreases by 10 (3d6) for every 24 hours that elapse. If the curse reduces the target''s hit point maximum to 0, the target dies and rises as a new graveyard revenant 24 hours later.','Actions',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('428f63d1-6281-4dec-93e0-95111ded2f27'::uuid,'01990b8e-1b92-75b0-8919-3ae08628359b'::uuid,'Amorphous. The ooze can move through a space as narrow as 1 inch without expending extra movement to do so.','Amorphous',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('9f9f8dd5-79d4-43c3-be77-eab70d95118a'::uuid,'01990b8e-1b92-75b0-8919-3ae08628359b'::uuid,'Corrosive Form. Nonmagical ammunition is destroyed immediately after hitting the ooze and dealing any damage. Any nonmagical weapon takes a cumulative -1 penalty to attack rolls immediately after dealing damage to the ooze and coming into contact with it. The weapon is destroyed if the penalty reaches -5. The penalty can be removed by casting the Mending spell on the weapon. The ooze can eat through 2-inch-thick, nonmagical metal or wood in 1 round.','Corrosive Form',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('c0d09d01-e942-42ac-8da8-7b454b4ffe02'::uuid,'01990b8e-3809-787f-a678-76156f563f91'::uuid,'Amphibious. The dragon can breathe air and water.','Amphibious',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('784cfa8e-5ed8-41bf-9e4f-1c8f5bf1469d'::uuid,'01990b8e-595e-7c24-b57f-98f71a97da4a'::uuid,'Mimicry. The hag can mimic animal sounds and humanoid voices. A creature that hears the sounds can tell they are imitations only with a successful DC 14 Wisdom (Insight) check.','Mimicry',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('9e766e6f-821f-4de4-a73a-71b2b6ebbe76'::uuid,'01990b8e-595e-7c24-b57f-98f71a97da4a'::uuid,'Coven Magic. While within 30 feet of at least two hag allies, the hag can cast one of the following spells, requiring no Material components, using the spell''s normal casting time, and using Intelligence as the spellcasting ability (spell save DC 11): Augury, Find Familiar, Identify, Locate Object, Scrying, or Unseen Servant. The hag must finish a Long Rest before using this trait to cast that spell again.','Coven Magic',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('b95c4b2e-a796-43c3-a3dc-c4f969b153c4'::uuid,'01990b8e-c90d-72f1-ba92-d76fdfcad08e'::uuid,'Celestial Restoration. If the naga dies, it returns to life in 1d6 days and regains all its Hit Points unless Dispel Evil and Good is cast on its remains.','Celestial Restoration',false,NULL,NULL,'d6',NULL,1,NULL,NULL,'If the naga dies'),
	 ('e4cffb98-aec4-4490-adf6-9d2bb37f979e'::uuid,'01990b8e-d167-74e6-a122-38e3448f6f7e'::uuid,'The Gulthias Blight makes two attacks: one with its bite and one with its tendrils. It can use its Rejuvenation if it dies.','Actions',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO public.traits (id,monster_id,description,title,is_optional,attack_bonus,damage_bonus,damage_dice,damage_type,number_damage_dice,advantage_condition,disadvantage_condition,trait_trigger) VALUES
	 ('a9cf3bf0-e778-458a-9664-1ca4058ba866'::uuid,'01990b8e-f1c3-7b76-bbaf-2b314565e51c'::uuid,'Draconic Origin. The half-dragon is related to a type of dragon associated with one of the following damage types (DM''s choice): Acid, Cold, Fire, Lightning, or Poison. This choice affects other aspects of the stat block.','Draconic Origin',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('83bbd42e-0851-498e-b9aa-d3dc06f95dc2'::uuid,'01990b8f-38a2-7353-b761-9b95700e93d8'::uuid,'If the revenant dies, it revives 24 hours later unless Dispel Evil and Good is cast on its remains. If it revives, it animates another Gargantuan object or structure elsewhere on the same plane of existence; it now looks different but uses the same stat block and returns with all its Hit Points.','Undead Restoration',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('bb54e201-c2b4-4601-a622-6fb46003eca4'::uuid,'01990b8f-38a2-7353-b761-9b95700e93d8'::uuid,'Constitution Saving Throw: DC 17, any creature that casts a spell while inside the revenant''s space. Failure: The spell fails and is wasted.','Haunted Zone',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'any creature that casts a spell while inside the revenant''s space'),
	 ('0ae643e2-fea6-44a0-9782-90c8ba3c312f'::uuid,'01990b8f-6a39-7a50-8ab0-cd3c09212d4c'::uuid,'Pack Tactics. The hound has Advantage on an attack roll against a creature if at least one of the hound''s allies is within 5 feet of the creature and the ally doesn''t have the Incapacitated condition.','Pack Tactics',false,NULL,NULL,NULL,NULL,NULL,'if at least one of the hound''s allies is within 5 feet of the creature and the ally doesn''t have the Incapacitated condition',NULL,NULL),
	 ('3157ecf5-aa35-4e61-9f5e-3c47950b6ce5'::uuid,'01990b8f-71d2-7644-a2d8-35d56b36921a'::uuid,'The helmed horror makes two longsword attacks.','Actions',false,NULL,NULL,'d8','Slashing',1,NULL,NULL,NULL),
	 ('9bfe2227-15fd-404e-bcd3-4d3d475889e6'::uuid,'01990b8f-9e92-7b17-84ea-1753824aef1a'::uuid,'Demonic Restoration. If the hezrou dies outside the Abyss, its body dissolves into ichor, and it gains a new body instantly, reviving with all its Hit Points somewhere in the Abyss.','Demonic Restoration',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('b9393190-5ecd-45ca-a421-c4309f00557d'::uuid,'01990b8f-9e92-7b17-84ea-1753824aef1a'::uuid,'Magic Resistance. The hezrou has Advantage on saving throws against spells and other magical effects.','Magic Resistance',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('b9fab02b-cb72-48b2-bd67-d2ea7109926f'::uuid,'01990b8f-9e92-7b17-84ea-1753824aef1a'::uuid,'Stench. Constitution Saving Throw: DC 16, any creature that starts its turn in a 10-foot Emanation originating from the hezrou. Failure: The target has the Poisoned condition until the start of its next turn.','Stench',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('92f07f16-b113-4860-83fc-8bebc94e6104'::uuid,'01990b8f-c2f1-73b2-90bb-6298d74f7131'::uuid,'Flyby. The hippogriff doesn''t provoke an Opportunity Attack when it flies out of an enemy''s reach.','Flyby',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('5073bb78-a1e5-4b73-a7d8-8eb14be936d0'::uuid,'01990b8f-d3ea-7cad-8439-8ffa394e7378'::uuid,'Hold Breath. The hippopotamus can hold its breath for 10 minutes.','Hold Breath',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO public.traits (id,monster_id,description,title,is_optional,attack_bonus,damage_bonus,damage_dice,damage_type,number_damage_dice,advantage_condition,disadvantage_condition,trait_trigger) VALUES
	 ('20b82ecd-2f9b-4939-ba2f-e3267c731c2b'::uuid,'01990b8f-ee12-764d-bc2d-18c0bda734b3'::uuid,'Aura of Authority. While in a 10-foot Emanation originating from the hobgoblin, the hobgoblin and its allies have Advantage on attack rolls and saving throws, provided the hobgoblin doesn''t have the Incapacitated condition.','Aura of Authority',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('1c11797c-5806-4f38-9540-ecd01919cf5d'::uuid,'01990b8f-f81c-7e0f-b4a8-89d37c601f8c'::uuid,'The hobgoblin warlord makes three melee attacks or two ranged attacks. It can use its Leadership action if it has it available.','Actions',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('6ed34620-3469-4635-abd8-66784f452907'::uuid,'01990b90-0f52-780e-ad21-d5dfaee219b4'::uuid,'Pack Tactics. The hobgoblin has Advantage on an attack roll against a creature if at least one of the hobgoblin''s allies is within 5 feet of the creature and the ally doesn''t have the Incapacitated condition.','Pack Tactics',false,NULL,NULL,NULL,NULL,NULL,'if at least one of the hobgoblin''s allies is within 5 feet of the creature and the ally doesn''t have the Incapacitated condition',NULL,NULL),
	 ('39f63c20-3eab-47e9-bc7a-b2a5ea34bf92'::uuid,'01990b90-2183-73d4-bf32-cf424be4cc15'::uuid,'Telepathic Bond. While the homunculus is on the same plane of existence as its master, the two of them can communicate telepathically with each other.','Telepathic Bond',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('23df1929-3fbf-407e-9d11-6cea7c7f4259'::uuid,'01990b90-433f-72a7-8465-b8b8dc517a80'::uuid,'The devil has Advantage on saving throws against spells and other magical effects.','Magic Resistance',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('4daeb38b-c518-453b-ab9a-697ba13cc54c'::uuid,'01990b90-433f-72a7-8465-b8b8dc517a80'::uuid,'If the devil dies outside the Nine Hells, its body disappears in sulfurous smoke, and it gains a new body instantly, reviving with all its Hit Points somewhere in the Nine Hells.','Diabolical Restoration',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('988500c9-926b-4707-a058-a4bddc29864e'::uuid,'01990b90-5108-7ff2-a063-d421e88d7f68'::uuid,'Water Breathing. The shark can breathe only underwater.','Water Breathing',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('024cf1b0-10ad-4056-8eb4-bacfa81bedc4'::uuid,'01990b90-6e36-777a-941e-d07bae44b83a'::uuid,'The hydra can hold its breath for 1 hour.','Hold Breath',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('323f0671-05d9-4abc-a69e-37fec11f1176'::uuid,'01990b90-6e36-777a-941e-d07bae44b83a'::uuid,'The hydra has five heads. Whenever the hydra takes 25 damage or more on a single turn, one of its heads dies. The hydra dies if all its heads are dead. At the end of each of its turns when it has at least one living head, the hydra grows two heads for each of its heads that died since its last turn, unless it has taken Fire damage since its last turn. The hydra regains 20 Hit Points when it grows new heads.','Multiple Heads',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('e335355c-227e-4c89-863b-9f4446a48a96'::uuid,'01990b90-6e36-777a-941e-d07bae44b83a'::uuid,'For each head the hydra has beyond one, it gets an extra Reaction that can be used only for Opportunity Attacks.','Reactive Heads',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
