	 ('81c0d37f-491e-48de-8082-b7360c4f2e5b'::uuid,'01990b90-7e95-74fb-b31e-8fa0039599f4'::uuid,'Pack Tactics. The hyena has Advantage on an attack roll against a creature if at least one of the hyena''s allies is within 5 feet of the creature and the ally doesn''t have the Incapacitated condition.','Pack Tactics',false,NULL,NULL,NULL,NULL,NULL,'if at least one of the hyena''s allies is within 5 feet of the creature and the ally doesn''t have the Incapacitated condition',NULL,NULL),
	 ('244145eb-ff4c-4b68-9e62-d6d3b2018609'::uuid,'01990b90-a159-734a-96be-817ca0c88f4a'::uuid,'Diabolical Restoration. If the devil dies outside the Nine Hells, its body disappears in sulfurous smoke, and it gains a new body instantly, reviving with all its Hit Points somewhere in the Nine Hells.','Diabolical Restoration',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('368f0506-6ba8-47e8-8df1-e389bbf923eb'::uuid,'01990b90-a159-734a-96be-817ca0c88f4a'::uuid,'Magic Resistance. The devil has Advantage on saving throws against spells and other magical effects.','Magic Resistance',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('292f52f0-3290-4b91-82af-45730c06f320'::uuid,'01990b90-bbd2-7941-9fe5-ba2969848b88'::uuid,'The mephit explodes when it dies. Constitution Saving Throw: DC 10, each creature in a 5-foot Emanation originating from the mephit. Failure: 5 (2d4) Cold damage. Success: Half damage.','Death Burst',false,NULL,NULL,'d4','Cold',2,NULL,NULL,'when it dies'),
	 ('c13c3e32-a0ff-400d-bf3f-282db37a6302'::uuid,'01990b90-d6e8-778d-99aa-2acd89ab5f33'::uuid,'Magic Resistance. The imp has Advantage on saving throws against spells and other magical effects.','Magic Resistance',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('49c06503-b154-457b-b5b3-59d556e129e1'::uuid,'01990b90-fcd2-7f82-95b8-cdb8e91b2d91'::uuid,'Succubus Form. When the incubus finishes a Long Rest, it can shape-shift into a Succubus, using that stat block instead of this one. Any equipment it is wearing or carrying isn''t transformed.','Succubus Form',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('a3fc18cc-64f2-4ba0-91f5-c2fb4b6a748f'::uuid,'01990b91-0314-793c-aaaf-fe1030f0b36b'::uuid,'Actions. Multiattack. Claws. Body Thief.','Actions',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('3a56dbe9-f936-4549-9b2c-abb83917a327'::uuid,'01990b91-217f-716b-ac50-5efbfbd0a978'::uuid,'Invisibility. The stalker has the Invisible condition.','Invisibility',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('d480a9be-1fd0-48c9-ae77-cacb9be8e3f3'::uuid,'01990b91-217f-716b-ac50-5efbfbd0a978'::uuid,'Air Form. The stalker can enter an enemy''s space and stop there. It can move through a space as narrow as 1 inch without expending extra movement to do so.','Air Form',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('3f9c1e7b-e801-4a3e-af04-c9a05e286b18'::uuid,'01990b91-4546-7d53-b9f9-c0071e625c63'::uuid,'Immutable Form. The golem can''t shape-shift.','Immutable Form',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO public.traits (id,monster_id,description,title,is_optional,attack_bonus,damage_bonus,damage_dice,damage_type,number_damage_dice,advantage_condition,disadvantage_condition,trait_trigger) VALUES
	 ('6c8cd572-9119-434a-b170-dabc8520f9bd'::uuid,'01990b91-4546-7d53-b9f9-c0071e625c63'::uuid,'Fire Absorption. Whenever the golem is subjected to Fire damage, it regains a number of Hit Points equal to the Fire damage dealt.','Fire Absorption',false,NULL,NULL,NULL,'Fire',NULL,NULL,NULL,NULL),
	 ('a24385c2-5800-4ad1-b2c3-c657f9e6d8b6'::uuid,'01990b91-4546-7d53-b9f9-c0071e625c63'::uuid,'Magic Resistance. The golem has Advantage on saving throws against spells and other magical effects.','Magic Resistance',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('2196d684-2b0d-430c-a727-43815dc5009c'::uuid,'01990b91-577e-757a-8349-3521752d9267'::uuid,'Actions. Multiattack. The jackalwere makes two attacks: one with its bite and one with its claws. Bite. Melee Weapon Attack: +3 to hit, reach 5 ft., one creature. Hit: 3 (1d6) piercing damage. Claws. Melee Weapon Attack: +3 to hit, reach 5 ft., one target. Hit: 4 (1d6 + 1) slashing damage.','Actions',false,NULL,NULL,'d6','Piercing',1,NULL,NULL,NULL),
	 ('e5ca6eee-05e2-4497-9a0e-194dbd27ab8f'::uuid,'01990b91-6501-79c4-914c-96a4d5127d8b'::uuid,'The kenku can take the Disengage or Hide action as a bonus action on each of its turns.','Actions',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('3657516a-20bb-4fbe-a855-aa43507aeff9'::uuid,'01990b91-7422-7f7b-ad0c-371cc1f81368'::uuid,'Hold Breath. The whale can hold its breath for 30 minutes.','Hold Breath',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('2022e31d-637e-4002-8803-cad72200c6ff'::uuid,'01990b91-a38f-7599-8a56-0270d2412fe2'::uuid,'Pack Tactics. The kobold has Advantage on an attack roll against a creature if at least one of the kobold''s allies is within 5 feet of the creature and the ally doesn''t have the Incapacitated condition.','Pack Tactics',false,NULL,NULL,NULL,NULL,NULL,'if at least one of the kobold''s allies is within 5 feet of the creature and the ally doesn''t have the Incapacitated condition',NULL,NULL),
	 ('ab224af3-d6ff-4749-97e5-254a4dbf9386'::uuid,'01990b91-a38f-7599-8a56-0270d2412fe2'::uuid,'Sunlight Sensitivity. While in sunlight, the kobold has Disadvantage on ability checks and attack rolls.','Sunlight Sensitivity',false,NULL,NULL,NULL,NULL,NULL,NULL,'While in sunlight',NULL),
	 ('45e7ae3a-529a-4a3d-a28b-ae5bf9cca6ef'::uuid,'01990b91-e8ea-740f-b9d6-fac6d647f248'::uuid,'Legendary Resistance (4/Day, or 5/Day in Lair). If the kraken fails a saving throw, it can choose to succeed instead.','Legendary Resistance',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('798071c9-6041-4108-97d0-e55ce6e60c0f'::uuid,'01990b91-e8ea-740f-b9d6-fac6d647f248'::uuid,'Siege Monster. The kraken deals double damage to objects and structures.','Siege Monster',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('813b1aa6-e2e4-4d49-acf2-3e2927dc4e3f'::uuid,'01990b91-e8ea-740f-b9d6-fac6d647f248'::uuid,'Amphibious. The kraken can breathe air and water.','Amphibious',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO public.traits (id,monster_id,description,title,is_optional,attack_bonus,damage_bonus,damage_dice,damage_type,number_damage_dice,advantage_condition,disadvantage_condition,trait_trigger) VALUES
	 ('0d967a1a-53a3-4a65-8199-25295fcbcdce'::uuid,'01990b92-0f8a-71ae-a5ff-450bfb8cce38'::uuid,'Amphibious. The kuo-toa can breathe air and water.','Amphibious',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('8fe96ea3-d229-437d-a235-d86c7db35773'::uuid,'01990b92-0f8a-71ae-a5ff-450bfb8cce38'::uuid,'Sunlight Sensitivity. While in sunlight, the kuo-toa has Disadvantage on ability checks and attack rolls.','Sunlight Sensitivity',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('92b20ef7-830f-4dc8-a527-8424465029d8'::uuid,'01990b92-1ad4-7e23-860d-d244ce5f7b0a'::uuid,'The Kuo-toa Archpriest can take 2 legendary actions, choosing from the options below. Only one legendary action option can be used at a time and only at the end of another creature''s turn. The Kuo-toa Archpriest regains spent legendary actions at the start of its turn. Detect. The Kuo-toa Archpriest makes a Wisdom (Perception) check. The Kuo-toa Archpriest can take this action at will. Shocking Touch (Costs 2 Actions). The Kuo-toa Archpriest makes a shocking touch attack. On a hit, the target takes 3d10 lightning damage.','Actions',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('876925a4-1a7b-41eb-9bf8-ac685d677250'::uuid,'01990b92-2455-7513-9341-53b9aa0893bd'::uuid,'The Kuo-toa Monitor can make two attacks: one with its bite and one with its pincer staff. Bite: Melee Weapon Attack: +4 to hit, reach 5 ft., one target. Hit: 4 (1d4 + 2) piercing damage. Pincer Staff: Melee Weapon Attack: +4 to hit, reach 5 ft., one target. Hit: 5 (1d6 + 2) bludgeoning damage.','Actions',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('a664d4a1-b700-4f80-8534-f624c5aaaf68'::uuid,'01990b92-2e33-729f-bc8a-7b5b0d9c9c26'::uuid,'The kuo-toa whip makes two attacks with its tentacle lash.','Actions',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('33d14f57-16f0-4d81-9198-20a6fed782f2'::uuid,'01990b92-6735-7466-b1ca-ac2244de89ed'::uuid,'If the lemure dies in the Nine Hells, it revives with all its Hit Points in 1d10 days unless it is killed by a creature under the effects of a Bless spell or its remains are sprinkled with Holy Water.','Hellish Restoration',false,NULL,NULL,'d10',NULL,1,NULL,NULL,NULL),
	 ('8495d7ae-9491-4f05-9597-7155768d12f9'::uuid,'01990b92-9ff9-71ba-aefd-421e84de6818'::uuid,'Spirit Jar. If destroyed, the lich reforms in 1d10 days if it has a spirit jar, reviving with all its Hit Points. The new body appears in an unoccupied space within the lich''s lair.','Spirit Jar',false,NULL,NULL,'d10',NULL,1,NULL,NULL,NULL),
	 ('c495e23f-ba0f-4009-a8c2-e75fb48d6ca7'::uuid,'01990b92-9ff9-71ba-aefd-421e84de6818'::uuid,'Legendary Resistance (4/Day, or 5/Day in Lair). If the lich fails a saving throw, it can choose to succeed instead.','Legendary Resistance',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('72e851dc-cf91-419b-a06f-9ba04bd5e8e3'::uuid,'01990b92-bfa9-75a2-a4f2-5a075ff1ac51'::uuid,'Pack Tactics. The lion has Advantage on an attack roll against a creature if at least one of the lion''s allies is within 5 feet of the creature and the ally doesn''t have the Incapacitated condition.','Pack Tactics',false,NULL,NULL,NULL,NULL,NULL,'if at least one of the lion''s allies is within 5 feet of the creature and the ally doesn''t have the Incapacitated condition',NULL,NULL),
	 ('8b5be227-b0dd-499a-91ef-c764db675c34'::uuid,'01990b92-bfa9-75a2-a4f2-5a075ff1ac51'::uuid,'Running Leap. With a 10-foot running start, the lion can Long Jump up to 25 feet.','Running Leap',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO public.traits (id,monster_id,description,title,is_optional,attack_bonus,damage_bonus,damage_dice,damage_type,number_damage_dice,advantage_condition,disadvantage_condition,trait_trigger) VALUES
	 ('4d06bb94-d489-49c0-a0db-ff297f978c79'::uuid,'01990b92-d136-73a4-8e83-5ad5de0d09ec'::uuid,'The lizard can climb difficult surfaces, including along ceilings, without needing to make an ability check.','Spider Climb',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('c5a513cd-a487-4844-9de3-83021550d195'::uuid,'01990b93-1c54-7090-bb80-392aa9995fa4'::uuid,'The mephit explodes when it dies. Dexterity Saving Throw: DC 11, each creature in a 5-foot Emanation originating from the mephit. Failure: 7 (2d6) Fire damage. Success: Half damage.','Death Burst',false,NULL,NULL,'d6','Fire',2,NULL,NULL,'when it dies'),
	 ('93d58e81-e0bf-48bb-94ae-3170eb59a048'::uuid,'01990b93-3d83-7a41-847a-f62e5c0b1e9a'::uuid,'The magmin explodes when it dies. Dexterity Saving Throw: DC 11, each creature in a 10-foot Emanation originating from the magmin. Failure: 7 (2d6) Fire damage. Success: Half damage.','Death Burst',false,NULL,NULL,'d6','Fire',2,NULL,NULL,'when it dies'),
	 ('b4d26fe2-d90e-48ed-849c-0c42f1148e6b'::uuid,'01990b93-a8ee-75a1-8e8f-a2190e84822c'::uuid,'The marilith can take one Reaction on every turn of combat.','Reactive',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('ed0d4a64-ec40-49fc-af48-93129c6e740a'::uuid,'01990b93-a8ee-75a1-8e8f-a2190e84822c'::uuid,'The marilith has Advantage on saving throws against spells and other magical effects.','Magic Resistance',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('fc9b67ca-3964-4b7f-9fbc-8f77a0ca361f'::uuid,'01990b93-a8ee-75a1-8e8f-a2190e84822c'::uuid,'If the marilith dies outside the Abyss, its body dissolves into ichor, and it gains a new body instantly, reviving with all its Hit Points somewhere in the Abyss.','Demonic Restoration',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('4dec784d-a1db-45e5-8aeb-7338bf541ba9'::uuid,'01990b93-eb07-73c9-8530-4ce0ab69f055'::uuid,'Amphibious. The merfolk can breathe air and water.','Amphibious',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('ac6c1a54-4155-4e59-bab2-a58f1fdd8ad9'::uuid,'01990b93-f616-77af-8ec4-491dcaa71acd'::uuid,'The merfolk wavebender makes two attacks with its coral trident or casts control water. Coral Trident. Melee Weapon Attack: +5 to hit, reach 5 ft., one target. Hit: 6 (1d6 + 3) piercing damage. Control Water (1/Day). The merfolk wavebender casts control water (as the spell) without requiring material components.','Actions',false,5,3,'d6','Piercing',1,NULL,NULL,NULL),
	 ('4ed15b3d-367a-478c-89d7-5f6cc9575ca3'::uuid,'01990b94-15d3-71cb-81c7-4e6e58caf071'::uuid,'Amphibious. The merrow can breathe air and water.','Amphibious',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('0b5185d7-7f14-4b47-a764-c9612aeefb9e'::uuid,'01990b94-295f-7c16-93d5-91a02c850c04'::uuid,'The mezzoloth makes two attacks: one with its bite and one with its claws. Bite: Melee Weapon Attack: +6 to hit, reach 5 ft., one target. Hit: 7 (1d8 + 3) piercing damage. Claws: Melee Weapon Attack: +6 to hit, reach 5 ft., one target. Hit: 11 (2d6 + 4) slashing damage.','Actions',false,6,3,'d8','Piercing',1,NULL,NULL,NULL);
INSERT INTO public.traits (id,monster_id,description,title,is_optional,attack_bonus,damage_bonus,damage_dice,damage_type,number_damage_dice,advantage_condition,disadvantage_condition,trait_trigger) VALUES
	 ('31c4b7ec-da9d-4324-b3dc-94bdb1196f57'::uuid,'01990b94-45d0-7aa2-ab46-a2a3d79b665d'::uuid,'Adhesive (Object Form Only). The mimic adheres to anything that touches it. A Huge or smaller creature adhered to the mimic has the Grappled condition (escape DC 13). Ability checks made to escape this grapple have Disadvantage.','Adhesive',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('ad15ee6b-4ee8-4e8d-94cc-05d0581c4d87'::uuid,'01990b94-6131-7af1-92d0-c446eb6b7ea7'::uuid,'Magic Resistance. The mind flayer has Advantage on saving throws against spells and other magical effects.','Magic Resistance',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('794581d9-d6f1-41b2-98b3-8cdbcbb93c0a'::uuid,'01990ba4-c421-75bc-a07e-40fec710eb31'::uuid,'Amphibious. The dragon can breathe air and water.','Amphibious',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('a1b40c9f-e32f-4d94-8c8b-cc469d630628'::uuid,'01990b94-6bac-7635-b1d6-fbcaa347d650'::uuid,'The mind flayer arcanist can take 3 legendary actions, choosing from the options below. Only one legendary action option can be used at a time and only at the end of another creature''s turn. The mind flayer arcanist regains spent legendary actions at the start of its turn. Cantrip. The mind flayer arcanist casts a cantrip. Spell (Costs 2 Actions). The mind flayer arcanist casts a spell of 1st or 2nd level. Psychic Drain (Costs 3 Actions). One creature charmed by the mind flayer arcanist takes 10 (3d6) psychic damage, and the mind flayer arcanist regains hit points equal to the damage dealt.','Actions',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('3c593224-880b-4b2e-88c3-1a2cfe764146'::uuid,'01990b94-9338-76fb-9ca0-e265241cda55'::uuid,'Actions. Mud Mephit can use its Muddy Claws and Hurl Mud.','Actions',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('eb184eac-d45f-4b9f-9f52-7d20790a490f'::uuid,'01990b94-9fd5-7d7e-b792-6249f7f5b476'::uuid,'Beast of Burden. The mule counts as one size larger for the purpose of determining its carrying capacity.','Beast of Burden',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('b67cd747-ae86-4c83-8000-84f5ec608c41'::uuid,'01990b94-fef4-7c41-8ec2-14e5055ad054'::uuid,'Legendary Resistance (3/Day, or 4/Day in Lair). If the mummy fails a saving throw, it can choose to succeed instead.','Legendary Resistance',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('c8293b8a-eedf-442a-9d28-7fecd7bdab56'::uuid,'01990b94-fef4-7c41-8ec2-14e5055ad054'::uuid,'Magic Resistance. The mummy has Advantage on saving throws against spells and other magical effects.','Magic Resistance',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('c96a2a95-c49e-4a2f-9981-6090f659bb0f'::uuid,'01990b94-fef4-7c41-8ec2-14e5055ad054'::uuid,'Undead Restoration. If destroyed, the mummy gains a new body in 24 hours if its heart is intact, reviving with all its Hit Points. The new body appears in an unoccupied space within the mummy''s lair. The heart is a Tiny object that has AC 17, HP 10, and Immunity to all damage except Fire.','Undead Restoration',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('e7cd8ce6-cc74-432d-b6bd-17ed4d2d99db'::uuid,'01990b95-04c0-7809-a5de-686aa748adb9'::uuid,'The myconid adult makes three fist attacks.','Actions',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO public.traits (id,monster_id,description,title,is_optional,attack_bonus,damage_bonus,damage_dice,damage_type,number_damage_dice,advantage_condition,disadvantage_condition,trait_trigger) VALUES
	 ('8ff82f2a-5728-42e3-8a94-b83db069cbcf'::uuid,'01990b95-13fe-7f70-a565-41604b26d0ce'::uuid,'The Myconid Sovereign can take 3 legendary actions, choosing from the options below. Only one legendary action option can be used at a time and only at the end of another creature''s turn. The Myconid Sovereign regains spent legendary actions at the start of its turn. Spore Cloud. The Myconid Sovereign releases a 10-foot-radius spore cloud centered on itself. The spore cloud spreads around corners, and its area is lightly obscured. It lasts until the start of the Myconid Sovereign''s next turn. The Myconid Sovereign can move through the spore cloud without being affected by it. Rapport Spores (Costs 2 Actions). The Myconid Sovereign targets one creature it can see within 10 feet of it. The target must succeed on a DC 15 Charisma saving throw or be affected by the Sovereign''s Rapport Spores. For 1 hour, the affected creature can communicate telepathically with the Myconid Sovereign, and the two don''t need to share a language. The spores can be expelled from the creature by any effect that cures disease. Sovereign''s Command (Costs 3 Actions). The Myconid Sovereign targets up to three other Myconids it can see within 120 feet of it. The targets can each use their reactions to move up to their speed and make one weapon attack. The targets can move before or after the attack. The Myconid Sovereign can choose the direction that each target moves. The targets don''t provoke opportunity attacks when moving in this way.','Actions',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('0500d8b3-f8d5-4f3d-9bec-316dd5931edf'::uuid,'01990b95-1ab0-7d2b-96d7-8110d9a75b75'::uuid,'Actions. Rapier. Melee Weapon Attack: +4 to hit, reach 5 ft., one target. Hit: 6 (1d8 + 2) piercing damage.','Actions',false,4,2,'d8','Piercing',1,NULL,NULL,NULL),
	 ('2272bd9a-dc7a-4b6e-98a3-6dcb0f411a02'::uuid,'01990b95-4ced-7982-a41f-3907042c6c55'::uuid,'The nalfeshnee has Advantage on saving throws against spells and other magical effects.','Magic Resistance',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('65f5b80b-b3ff-498c-9899-d466eb620b79'::uuid,'01990b95-4ced-7982-a41f-3907042c6c55'::uuid,'If the nalfeshnee dies outside the Abyss, its body dissolves into ichor, and it gains a new body instantly, reviving with all its Hit Points somewhere in the Abyss.','Demonic Restoration',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('02d24dc3-aab6-41b4-94c2-19c8904c2cfc'::uuid,'01990b95-7fd5-7405-8962-c8e839033bb7'::uuid,'Soul Bag. The hag has a soul bag. While holding or carrying the bag, the hag can use its Nightmare Haunting action. The bag has AC 15, HP 20, and Resistance to all damage. The bag turns to dust if reduced to 0 Hit Points. If the bag is destroyed, any souls the bag is hol','Soul Bag',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('17be5f13-dc95-42b8-9fbe-e42074585401'::uuid,'01990b95-7fd5-7405-8962-c8e839033bb7'::uuid,'Coven Magic. While within 30 feet of at least two hag allies, the hag can cast one of the following spells, requiring no Material components, using the spell''s normal casting time, and using Intelligence as the spellcasting ability (spell save DC 14): Augury, Find Familiar, Identify, Locate Object, Scrying, or Unseen Servant. The hag must finish a Long Rest before using this trait to cast that spell again.','Coven Magic',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('38d6c94d-403f-4349-bbb8-55da1792a65a'::uuid,'01990b95-7fd5-7405-8962-c8e839033bb7'::uuid,'Magic Resistance. The hag has Advantage on saving throws against spells and other magical effects.','Magic Resistance',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('61dfb736-9ef6-4d2b-b48e-fdf1c8be9f37'::uuid,'01990b95-9841-7349-990c-db209e9d786e'::uuid,'Confer Fire Resistance. The nightmare can grant Resistance to Fire damage to a rider while it is on the nightmare.','Confer Fire Resistance',false,NULL,NULL,NULL,'Fire',NULL,NULL,NULL,NULL),
	 ('b559ce36-429a-4936-b1c4-0add43e017c7'::uuid,'01990b95-9841-7349-990c-db209e9d786e'::uuid,'Illumination. The nightmare sheds Bright Light in a 10-foot radius and Dim Light for an additional 10 feet.','Illumination',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('74448d81-8f3c-42a3-b7da-bf0c40f88999'::uuid,'01990b95-c96c-7a2f-8200-c81abe666305'::uuid,'The nycaloth makes two attacks: one with its longsword and one with its tail. It can use its Teleport without provoking opportunity attacks.','Actions',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
