	 ('89556940-7eb2-486d-8e60-36150fb90686'::uuid,'01990b95-e4af-73f2-b801-4adb75f30777'::uuid,'Spider Climb. The jelly can climb difficult surfaces, including along ceilings, without needing to make an ability check.','Spider Climb',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('b6f998e6-926e-4f6f-be5f-392a9677b495'::uuid,'01990b95-e4af-73f2-b801-4adb75f30777'::uuid,'Amorphous. The jelly can move through a space as narrow as 1 inch without expending extra movement to do so.','Amorphous',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('9c0478e3-77cc-4e9f-a813-ffced28e344f'::uuid,'01990b96-141a-7c8e-a5ac-ebc1d7950b47'::uuid,'Compression. The octopus can move through a space as narrow as 1 inch without spending extra movement to do so.','Compression',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('dd2153dc-72a6-40d0-abc3-a9f205e67a6f'::uuid,'01990b96-141a-7c8e-a5ac-ebc1d7950b47'::uuid,'Water Breathing. The octopus can breathe only underwater.','Water Breathing',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('8d3ad331-df42-4ef5-aa51-6556d655a284'::uuid,'01990b96-40d7-77e8-800f-70598f4d229f'::uuid,'Undead Fortitude. If damage reduces the zombie to 0 Hit Points, it makes a Constitution saving throw (DC 5 plus the damage taken) unless the damage is Radiant or from a Critical Hit. On a successful save, the zombie drops to 1 Hit Point instead.','Undead Fortitude',false,NULL,NULL,NULL,'Radiant',NULL,NULL,NULL,'damage reduces the zombie to 0 Hit Points'),
	 ('cfaa06b7-e48d-439b-b2af-3639b95def9b'::uuid,'01990b96-6e90-76e8-b678-74bb26715be0'::uuid,'Regeneration. The oni regains 10 Hit Points at the start of each of its turns if it has at least 1 Hit Point.','Regeneration',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('ee3d48fb-c0b0-4ea8-ab41-8b05152d70f3'::uuid,'01990b96-ae8b-741f-9bf9-785e774fecbf'::uuid,'Flyby. The owl doesn''t provoke Opportunity Attack action when it flies out of an enemy''s reach.','Flyby',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('e829fce9-39ad-473a-b202-95c33efb31d4'::uuid,'01990b97-01f6-7da7-8612-67543bde9acb'::uuid,'The Peryton makes two attacks: one with its beak and one with its antlers. If both attacks hit a Medium or smaller target, the target must succeed on a DC 13 Strength saving throw or be knocked prone. Beak: Melee Weapon Attack: +6 to hit, reach 5 ft., one target. Hit: 7 (1d6 + 4) piercing damage. Antlers: Melee Weapon Attack: +6 to hit, reach 5 ft., one target. Hit: 9 (2d6 + 2) piercing damage.','Actions',false,NULL,NULL,'d6','Piercing',1,NULL,NULL,NULL),
	 ('7914ad6c-a879-47a6-b5f3-686ea5b52dee'::uuid,'01990ba4-e2c5-7577-9e5b-0a2aa37753fa'::uuid,'Amphibious. The dragon can breathe air and water.','Amphibious',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('1c120c09-d7e1-40e5-a5d7-11b446a6a837'::uuid,'01990b97-2be6-7cc9-b556-b14da970f7b9'::uuid,'The Piercer makes one attack with its shell spine. Melee Weapon Attack: +4 to hit, reach 5 ft., one target. Hit: 6 (1d6 + 3) piercing damage.','Actions',false,4,3,'d6','Piercing',1,NULL,NULL,NULL);
INSERT INTO public.traits (id,monster_id,description,title,is_optional,attack_bonus,damage_bonus,damage_dice,damage_type,number_damage_dice,advantage_condition,disadvantage_condition,trait_trigger) VALUES
	 ('00ff79a2-6564-4b49-b8d2-f463aed3f225'::uuid,'01990b97-3aae-71fe-99a0-563abef3843b'::uuid,'Water Breathing. The piranha can breathe only underwater.','Water Breathing',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('5aa9e781-3e20-4613-8196-188893bf9589'::uuid,'01990b97-aa44-7ab6-bef5-4beac1312331'::uuid,'The pit fiend emanates an aura in a 20-foot Emanation while it doesn''t have the Incapacitated condition. Wisdom Saving Throw: DC 21, any enemy that starts its turn in the aura. Failure: The target has the Frightened condition until the start of its next turn. Success: The target is immune to this pit fiend''s aura for 24 hours.','Fear Aura',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('8f4ccd31-cae3-4825-bd74-b684889cfe7f'::uuid,'01990b97-aa44-7ab6-bef5-4beac1312331'::uuid,'If the pit fiend dies outside the Nine Hells, its body disappears in sulfurous smoke, and it gains a new body instantly, reviving with all its Hit Points somewhere in the Nine Hells.','Diabolical Restoration',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('a5120960-f8d0-42de-9f21-4c62f9fe547c'::uuid,'01990b97-aa44-7ab6-bef5-4beac1312331'::uuid,'The pit fiend has Advantage on saving throws against spells and other magical effects.','Magic Resistance',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('af07e66d-048f-43f0-9beb-a04022903eb2'::uuid,'01990b97-aa44-7ab6-bef5-4beac1312331'::uuid,'If the pit fiend fails a saving throw, it can choose to succeed instead.','Legendary Resistance (4/Day)',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('a88a4e9a-644e-408b-996a-d395eff8b66d'::uuid,'01990b97-b1b4-708c-b748-3e5654731264'::uuid,'Actions. The pixie can use its Magic Resistance to cast polymorph on itself, transforming into a beast form with a challenge rating of 1/4 or lower, or back into its true form. Its statistics are the same in each form, except for the speed changes noted. Any equipment it is wearing or carrying isn''t transformed. It reverts to its true form if it dies.','Actions',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('41312c13-af19-493d-98f7-6fc25a78adb2'::uuid,'01990b97-b994-766c-846f-2b1739d83747'::uuid,'The pixie wonderbringer can take the following actions.','Actions',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('614ac0fb-7746-425d-9455-664849cddeb1'::uuid,'01990b97-fc76-72a6-afa9-1b7baa7356e7'::uuid,'Magic Resistance. The planetar has Advantage on saving throws against spells and other magical effects.','Magic Resistance',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('a2cd1360-f1be-4836-8730-44f7aed3fcde'::uuid,'01990b97-fc76-72a6-afa9-1b7baa7356e7'::uuid,'Divine Awareness. The planetar knows if it hears a lie.','Divine Awareness',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('c06fa9fb-ec8b-4e43-8e4f-59200cd354f2'::uuid,'01990b97-fc76-72a6-afa9-1b7baa7356e7'::uuid,'Exalted Restoration. If the planetar dies outside Mount Celestia, its body disappears, and it gains a new body instantly, reviving with all its Hit Points somewhere in Mount Celestia.','Exalted Restoration',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO public.traits (id,monster_id,description,title,is_optional,attack_bonus,damage_bonus,damage_dice,damage_type,number_damage_dice,advantage_condition,disadvantage_condition,trait_trigger) VALUES
	 ('36931fa6-a186-4f8b-82a2-6c95000ea088'::uuid,'01990b98-0b97-70e5-9e05-f54fe129ccb2'::uuid,'Hold Breath. The plesiosaurus can hold its breath for 1 hour.','Hold Breath',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('3f2006e4-97eb-48d7-a724-8202464a6317'::uuid,'01990b98-20ab-7d35-a999-ed9935a49a1c'::uuid,'The poltergeist can use its Frightening Visage. It then makes one attack with its Possession. It can use its Telekinetic Thrust in place of its attack.','Actions',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('88d61ab8-3ce3-4207-b81e-da2671e57824'::uuid,'01990b98-6e57-7f4c-b654-68dd6e5b08fe'::uuid,'The Primeval Owlbear can take 2 actions: Multiattack and Beak.','Actions',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('4cc733ae-5088-42b0-b181-a70868e81d60'::uuid,'01990b98-8592-7920-935d-97867b9345cb'::uuid,'Magic Resistance. The pseudodragon has Advantage on saving throws against spells and other magical effects.','Magic Resistance',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('62d1cf1c-b787-4af3-b818-84b066e27ab0'::uuid,'01990b98-9163-764a-8dda-423671a6312c'::uuid,'The psychic gray ooze makes two pseudopod attacks. If both attacks hit a Medium or smaller target, the target must succeed on a DC 14 Intelligence saving throw or take 10 (3d6) psychic damage and be stunned until the end of the psychic gray ooze''s next turn.','Actions',false,NULL,NULL,'d6','Psychic',3,NULL,NULL,NULL),
	 ('92fc796f-b38c-4792-9e8c-0bd3c31cc7e7'::uuid,'01990b98-9e5a-72db-b8ca-65afee882069'::uuid,'Flyby. The pteranodon doesn''t provoke an Opportunity Attack when it flies out of an enemy''s reach.','Flyby',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('e28f956b-a0df-4002-9519-e7ac3d924042'::uuid,'01990b98-c8c2-770c-a59a-a85a42827d1e'::uuid,'Tunneler. The worm can burrow through solid rock at half its Burrow Speed and leaves a 10-foot-diameter tunnel in its wake.','Tunneler',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('998909bd-05be-48ea-8f62-60a6b6c0df4a'::uuid,'01990b98-ce32-7b63-a49b-7d7c1d00641a'::uuid,'The quaggoth makes two morningstar attacks.','Actions',false,NULL,NULL,'d8','Bludgeoning',1,NULL,NULL,NULL),
	 ('2c901d7a-aa20-4cb4-9b32-9c1930296062'::uuid,'01990b98-dcf3-77dc-a635-5cc1cb3d4dcd'::uuid,'Melee Weapon Attack: +4 to hit, reach 5 ft., one target. Hit: 8 (2d6 + 2) piercing damage.','Bite',false,4,2,'d6','Piercing',2,NULL,NULL,NULL),
	 ('31050307-9636-444b-8880-8463c7374cc7'::uuid,'01990b98-dcf3-77dc-a635-5cc1cb3d4dcd'::uuid,'Melee Weapon Attack: +4 to hit, reach 5 ft., one target. Hit: 7 (2d4 + 2) slashing damage.','Claw',false,4,2,'d4','Slashing',2,NULL,NULL,NULL);
INSERT INTO public.traits (id,monster_id,description,title,is_optional,attack_bonus,damage_bonus,damage_dice,damage_type,number_damage_dice,advantage_condition,disadvantage_condition,trait_trigger) VALUES
	 ('7339e800-484e-4d42-bb15-1e0da9e945b9'::uuid,'01990b98-dcf3-77dc-a635-5cc1cb3d4dcd'::uuid,'The quaggoth makes two melee attacks.','Multiattack',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('b5f5e390-55c6-41da-bc5f-2cd55bf04a0b'::uuid,'01990b99-0193-7ff5-af07-4e6b690c14ab'::uuid,'Magic Resistance. The quasit has Advantage on saving throws against spells and other magical effects.','Magic Resistance',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('78793753-8976-4f71-b2bc-02a87e766524'::uuid,'01990b99-2af4-77f3-a870-49c221aed164'::uuid,'Greater Magic Resistance. The rakshasa automatically succeeds on saving throws against spells and other magical effects, and the attack rolls of spells automatically miss it. Without the rakshasa''s permission, no spell can observe the rakshasa remotely or detect its thoughts, creature type, or alignment.','Greater Magic Resistance',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('db54f47f-d90e-4b90-8a97-6bd0b8e8247d'::uuid,'01990b99-2af4-77f3-a870-49c221aed164'::uuid,'Fiendish Restoration. If the rakshasa dies outside the Nine Hells, its body turns to ichor, and it gains a new body instantly, reviving with all its Hit Points somewhere in the Nine Hells.','Fiendish Restoration',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('a12c8260-9c19-47eb-942b-5a7e8d06fa4a'::uuid,'01990b99-37da-7b6a-8a53-9e5d69fef3a8'::uuid,'Agile. The rat doesn''t provoke Opportunity Attack action when it moves out of an enemy''s reach.','Agile',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('c9124a87-a9e7-4e4a-8a81-315f9f7b4064'::uuid,'01990b99-44b3-76cb-a0a5-43abbb88098f'::uuid,'Mimicry. The raven can mimic simple sounds it has heard, such as a whisper or chitter. A hearer can discern the sounds are imitations with a successful DC 10 Wisdom (Insight) check.','Mimicry',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('6b539ebb-771b-46e0-85a2-e30c22901e41'::uuid,'01990b99-5f47-794c-ba88-d1e9d2971fcc'::uuid,'The Red Slaad can take 3 legendary actions, choosing from the options below. Only one legendary action option can be used at a time and only at the end of another creature''s turn. The Red Slaad regains spent legendary actions at the start of its turn. Detect. The Red Slaad makes a Wisdom (Perception) check. Teleport. The Red Slaad magically teleports, along with any equipment it is wearing or carrying, up to 120 feet to an unoccupied space it can see.','Actions',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('dbf0416c-70e1-45ca-ae3d-9b1efe7b3acd'::uuid,'01990b99-7329-775d-9640-522d26f93c52'::uuid,'Pack Tactics. The shark has Advantage on an attack roll against a creature if at least one of the shark''s allies is within 5 feet of the creature and the ally doesn''t have the Incapacitated condition.','Pack Tactics',false,NULL,NULL,NULL,NULL,NULL,'if at least one of the shark''s allies is within 5 feet of the creature and the ally doesn''t have the Incapacitated condition',NULL,NULL),
	 ('ec4e023b-3428-48d8-8194-37fb14e3004f'::uuid,'01990b99-7329-775d-9640-522d26f93c52'::uuid,'Water Breathing. The shark can breathe only underwater.','Water Breathing',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('db004d13-ae4e-4bef-9f02-fa4d18109cbf'::uuid,'01990b99-96a5-73c1-81f5-9cc648ade295'::uuid,'At the end of each of the remorhaz''s turns, each creature in a 5-foot Emanation originating from the remorhaz takes 16 (3d10) Fire damage.','Heat Aura',false,NULL,NULL,'d10','Fire',3,NULL,NULL,'At the end of each of the remorhaz''s turns');
INSERT INTO public.traits (id,monster_id,description,title,is_optional,attack_bonus,damage_bonus,damage_dice,damage_type,number_damage_dice,advantage_condition,disadvantage_condition,trait_trigger) VALUES
	 ('b4df0e21-fda6-431a-8aa8-8a12d9dd685f'::uuid,'01990b99-a20e-755f-b375-625644d25079'::uuid,'The Revenant makes two fist attacks.','Actions',false,NULL,NULL,'d6','Bludgeoning',1,NULL,NULL,NULL),
	 ('3e8212bf-af68-4b0e-a9b0-049edbb45421'::uuid,'01990b99-eb5a-7bff-a763-04c86a9ca761'::uuid,'The roper can climb difficult surfaces, including along ceilings, without needing to make an ability check.','Spider Climb',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('798a51da-e8da-4b51-b8e0-297fb96aadbe'::uuid,'01990b9a-0d53-779a-9bee-d3b2886d72d1'::uuid,'Iron Scent. The rust monster can pinpoint the location of ferrous metal within 30 feet of itself.','Iron Scent',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('8bdc1942-7203-4214-9d61-7f595cc0bfa5'::uuid,'01990b9a-283f-7289-9843-8c0eab8e2103'::uuid,'With a 10-foot running start, the tiger can Long Jump up to 25 feet.','Running Leap',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('c447a1ad-abb7-458f-a9a1-71eade756649'::uuid,'01990b9a-3561-77cd-af86-511735cab681'::uuid,'The sahuagin baron makes three attacks: one with its bite and two with its claws or trident. If the baron is wielding a trident, it can also use its Blood Frenzy.','Actions',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('29182a87-8432-44a8-946e-21650b0567da'::uuid,'01990b9a-454b-70c6-9bc0-14752c5dc3f1'::uuid,'The sahuagin priest makes two attacks with its claws or trident. It can use its Channel Divinity once, choosing one of the following options: Turn the Unbeliever. The sahuagin priest presents its holy symbol and speaks a prayer of denunciation, targeting one fiend or undead it can see within 30 feet of it. The target must make a Wisdom saving throw. On a failed save, the creature is turned for 1 minute or until it takes damage. A turned creature must spend its turns trying to move as far away from the sahuagin priest as it can, and it can''t willingly move to a space within 30 feet of the priest. It also can''t take reactions. For its action, it can use only the Dash action or try to escape from an effect that prevents it from moving. If there''s nowhere to move, the creature can use the Dodge action. Invoke Drowned Devotion. The sahuagin priest calls upon its god to curse a creature it can see within 30 feet of it. The target must succeed on a Wisdom saving throw or be cursed for 1 minute. While cursed, the target must make a Wisdom saving throw at the start of each of its turns. If it fails, it wastes its action that turn doing nothing. If it succeeds, it can act normally. The curse ends if the target dies, if the sahuagin priest dies, or if the sahuagin priest is incapacitated. The curse also ends after 1 minute.','Actions',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('42cbf218-05c0-4062-9b7d-5ec17fa49dc9'::uuid,'01990b9a-68a7-7a84-a4e0-ea7d9ad79cdc'::uuid,'Blood Frenzy. The sahuagin has Advantage on attack rolls against any creature that doesn''t have all its Hit Points.','Blood Frenzy',false,NULL,NULL,NULL,NULL,NULL,'against any creature that doesn''t have all its Hit Points',NULL,NULL),
	 ('5dcdf531-0abf-464b-b1b4-14c947e0291a'::uuid,'01990b9a-68a7-7a84-a4e0-ea7d9ad79cdc'::uuid,'Shark Telepathy. The sahuagin can magically control sharks within 120 feet of itself, using a special telepathy.','Shark Telepathy',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('cfd1f0c2-1735-4b80-b4ae-cd2afd2fca8d'::uuid,'01990b9a-68a7-7a84-a4e0-ea7d9ad79cdc'::uuid,'Limited Amphibiousness. The sahuagin can breathe air and water, but it must be submerged at least once every 4 hours to avoid suffocating outside water.','Limited Amphibiousness',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('aef71d8b-6ee4-432f-a4aa-e1a9f9809315'::uuid,'01990b9a-8758-7f95-a445-be36736917cf'::uuid,'Fire Aura. At the end of each of the salamander''s turns, each creature of the salamander''s choice in a 5-foot Emanation originating from the salamander takes 7 (2d6) Fire damage.','Fire Aura',false,NULL,NULL,'d6','Fire',2,NULL,NULL,'At the end of each of the salamander''s turns');
INSERT INTO public.traits (id,monster_id,description,title,is_optional,attack_bonus,damage_bonus,damage_dice,damage_type,number_damage_dice,advantage_condition,disadvantage_condition,trait_trigger) VALUES
	 ('2883d8d3-98fb-4559-80ed-c78631940fac'::uuid,'01990b9a-8da7-715e-9aa3-e9118da71461'::uuid,'The salamander makes two attacks: one with its spear and one with its tail. Alternatively, it can use its Multiattack twice.','Actions',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('197b64d8-ec23-4fe0-be61-81b5f7e20b50'::uuid,'01990b9a-9ea6-7000-929c-f63254b1c7de'::uuid,'The salamander makes two attacks: one with its spear and one with its tail. Spear: Melee Weapon Attack: +7 to hit, reach 10 ft., one target. Hit: 11 (2d6 + 4) piercing damage, or 13 (2d8 + 4) piercing damage if used with two hands to make a melee attack, plus 7 (2d6) fire damage. Tail: Melee Weapon Attack: +7 to hit, reach 10 ft., one target. Hit: 11 (2d6 + 4) bludgeoning damage plus 7 (2d6) fire damage.','Actions',false,7,4,'d6','Piercing',2,NULL,NULL,NULL),
	 ('33c8055b-bb11-4df6-b989-7934b6bb3cdf'::uuid,'01990b9a-af9d-7b43-9798-39e69b39e965'::uuid,'Magic Resistance. The satyr has Advantage on saving throws against spells and other magical effects.','Magic Resistance',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('70999d2d-26d0-467c-bbdf-4ed73656ca85'::uuid,'01990b9a-b6e9-7f05-8f2d-a5e77f2e286c'::uuid,'The satyr revelmaster makes two attacks with its shortsword or two attacks with its shortbow. It can use its Pan Flute of Pandemonium in place of one shortsword attack.','Actions',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('04280fc9-bb09-45db-9f9a-6f6f65520121'::uuid,'01990b9b-1034-7f2b-8d19-80002f454224'::uuid,'While within 30 feet of at least two hag allies, the hag can cast one of the following spells, requiring no Material components, using the spell''s normal casting time, and using Intelligence as the spellcasting ability (spell save DC 11): Augury, Find Familiar, Identify, Locate Object, Scrying, or Unseen Servant. The hag must finish a Long Rest before using this trait to cast that spell again.','Coven Magic',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('4d4a873f-e0f6-4e89-b089-db5a56a2e694'::uuid,'01990b9b-1034-7f2b-8d19-80002f454224'::uuid,'Wisdom Saving Throw: DC 11, any Beast or Humanoid that starts its turn within 30 feet of the hag and can see the hag''s true form. Failure: The target has the Frightened condition until the start of its next turn. Success: The target is immune to this hag''s Vile Appearance for 24 hours.','Vile Appearance',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('e341074b-8c9d-4a6e-8ab0-f314a20a6df0'::uuid,'01990b9b-1034-7f2b-8d19-80002f454224'::uuid,'The hag can breathe air and water.','Amphibious',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('538a7ecd-6ba3-4b6f-8864-c80a9dc8526f'::uuid,'01990b9b-1e93-7b5b-a424-19eba0ef381e'::uuid,'Water Breathing. The seahorse can breathe only underwater.','Water Breathing',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('41af8e18-8b82-4162-902e-c9842e1a9345'::uuid,'01990b9b-3785-7e2b-af68-7fe6fce62bb8'::uuid,'Sunlight Weakness. While in sunlight, the shadow has Disadvantage on D20 Tests.','Sunlight Weakness',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('e3362843-1fb9-403e-a9af-b403b4066654'::uuid,'01990b9b-3785-7e2b-af68-7fe6fce62bb8'::uuid,'Amorphous. The shadow can move through a space as narrow as 1 inch without expending extra movement to do so.','Amorphous',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO public.traits (id,monster_id,description,title,is_optional,attack_bonus,damage_bonus,damage_dice,damage_type,number_damage_dice,advantage_condition,disadvantage_condition,trait_trigger) VALUES
	 ('8f4e3df6-a7d1-4bd9-ad31-c0ae72843d42'::uuid,'01990b9b-4b16-700a-a615-9ee35cd340d4'::uuid,'The shadow dragon can use its Frightful Presence. It then makes three attacks: one with its bite and two with its claws.','Actions',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('6be77f73-4164-498b-83c0-f791e0164a95'::uuid,'01990b9b-6338-7573-8ffc-68f87abc8781'::uuid,'Lightning Absorption. Whenever the shambling mound is subjected to Lightning damage, it regains a number of Hit Points equal to the Lightning damage dealt.','Lightning Absorption',false,NULL,NULL,NULL,'Lightning',NULL,NULL,NULL,'Whenever the shambling mound is subjected to Lightning damage'),
	 ('367de0da-275a-4956-9a30-08c2f5274bcd'::uuid,'01990b9b-84af-7d50-8cd0-8e0a87af88e7'::uuid,'A spellcaster who wears the guardian''s amulet can cause the guardian to store one spell of level 4 or lower. To do so, the wearer must cast the spell on the guardian while within 5 feet of it. The spell has no effect but is stored within the guardian. Any previously stored spell is lost when a new spell is stored. The guardian can cast the spell stored with any parameters set by the original caster, requiring no spell components and using the caster''s spellcasting ability. The stored spell is then lost.','Spell Storing',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('9a5dfdd0-db17-4480-bd97-97e5773f3ed8'::uuid,'01990b9b-84af-7d50-8cd0-8e0a87af88e7'::uuid,'The guardian regains 10 Hit Points at the start of each of its turns if it has at least 1 Hit Point.','Regeneration',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('fa73d69a-b8dd-4e18-a7a8-895eaee5f786'::uuid,'01990b9b-84af-7d50-8cd0-8e0a87af88e7'::uuid,'The guardian is magically bound to an amulet. While the guardian and its amulet are on the same plane of existence, the amulet''s wearer can telepathically call the guardian to travel to it, and the guardian knows the distance and direction to the amulet. If the guardian is within 60 feet of the amulet''s wearer, half of any damage the wearer takes (round up) is transferred to the guardian.','Bound',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('42ad3f3d-73d6-42cb-81f3-bad93f74f365'::uuid,'01990b9b-be81-714c-8a96-1504fc180739'::uuid,'Magic Resistance. The slaad has Advantage on saving throws against spells and other magical effects.','Magic Resistance',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('b3b52415-089f-46fe-acf0-23cdb3a418f4'::uuid,'01990b9b-c709-72f9-ae96-1c28873c30e7'::uuid,'The smoke mephit can use its Smoke Breath. It then makes two claw attacks.','Actions',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('cc6cca0e-71bd-49bc-a206-a3cc499eaa2c'::uuid,'01990b9b-ff64-76fd-ba20-d5435afba9f4'::uuid,'Magic Resistance. The solar has Advantage on saving throws against spells and other magical effects.','Magic Resistance',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('e6b6db57-896b-4580-9d24-51b8f187c956'::uuid,'01990b9b-ff64-76fd-ba20-d5435afba9f4'::uuid,'Legendary Resistance (4/Day). If the solar fails a saving throw, it can choose to succeed instead.','Legendary Resistance (4/Day)',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('ef9f4a77-be82-4165-acac-ae2a5f13af38'::uuid,'01990b9b-ff64-76fd-ba20-d5435afba9f4'::uuid,'Exalted Restoration. If the solar dies outside Mount Celestia, its body disappears, and it gains a new body instantly, reviving with all its Hit Points somewhere in Mount Celestia.','Exalted Restoration',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO public.traits (id,monster_id,description,title,is_optional,attack_bonus,damage_bonus,damage_dice,damage_type,number_damage_dice,advantage_condition,disadvantage_condition,trait_trigger) VALUES
	 ('fc43aaec-96df-49ef-b3b6-3477da69645e'::uuid,'01990b9b-ff64-76fd-ba20-d5435afba9f4'::uuid,'Divine Awareness. The solar knows if it hears a lie.','Divine Awareness',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('3032cc86-6c53-41ff-8224-58e62bd9a21b'::uuid,'01990b9c-12de-79f6-83bc-a27b1119d392'::uuid,'Incorporeal Movement. The specter can move through other creatures and objects as if they were Difficult Terrain. It takes 5 (1d10) Force damage if it ends its turn inside an object.','Incorporeal Movement',false,NULL,NULL,'d10','Force',1,NULL,NULL,'if it ends its turn inside an object'),
	 ('a39b9cc6-573c-4f9c-a6b9-fbb0d85e2b98'::uuid,'01990b9c-12de-79f6-83bc-a27b1119d392'::uuid,'Sunlight Sensitivity. While in sunlight, the specter has Disadvantage on ability checks and attack rolls.','Sunlight Sensitivity',false,NULL,NULL,NULL,NULL,NULL,NULL,'While in sunlight',NULL),
	 ('4fafeb46-f0e8-4c78-95d4-70faecd75f94'::uuid,'01990b9c-448b-766b-b406-884f0c13df26'::uuid,'Inscrutable. No magic can observe the sphinx remotely or detect its thoughts without its permission. Wisdom (Insight) checks made to ascertain its intentions or sincerity are made with Disadvantage.','Inscrutable',false,NULL,NULL,NULL,NULL,NULL,NULL,'No magic can observe the sphinx remotely or detect its thoughts without its permission. Wisdom (Insight) checks made to ascertain its intentions or sincerity are made with Disadvantage.',NULL),
	 ('d7057a5a-fa63-4023-8243-eb5e018008c9'::uuid,'01990b9c-448b-766b-b406-884f0c13df26'::uuid,'Legendary Resistance (3/Day, or 4/Day in Lair). If the sphinx fails a saving throw, it can choose to succeed instead.r).','Legendary Resistance',false,NULL,NULL,NULL,NULL,NULL,NULL,'If the sphinx fails a saving throw, it can choose to succeed instead.r).',NULL),
	 ('65380ab1-3ab0-4d3a-b5d4-ae7b54e6ea51'::uuid,'01990b9c-8dc7-70a2-825f-e4e7f1eb7123'::uuid,'Inscrutable. No magic can observe the sphinx remotely or detect its thoughts without its permission. Wisdom (Insight) checks made to ascertain its intentions or sincerity are made with Disadvantage.','Inscrutable',false,NULL,NULL,NULL,NULL,NULL,NULL,'Wisdom (Insight) checks made to ascertain its intentions or sincerity',NULL),
	 ('84c4af12-5621-446e-8bfa-e694bd835c06'::uuid,'01990b9c-8dc7-70a2-825f-e4e7f1eb7123'::uuid,'Legendary Resistance (3/Day, or 4/Day in Lair). If the sphinx fails a saving throw, it can choose to succeed instead.','Legendary Resistance',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('53e30d4f-eaa9-4d8a-836e-6e19fac92ff8'::uuid,'01990b9c-a5b6-7f0b-8041-2f75b72eeb76'::uuid,'Magic Resistance. The sphinx has Advantage on saving throws against spells and other magical effects.','Magic Resistance',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('42dc7137-6b0f-49ae-932c-e8bddb2f1570'::uuid,'01990b9c-bd39-7ff6-b85d-02672802e040'::uuid,'The spider ignores movement restrictions caused by webs, and the spider knows the location of any other creature in contact with the same web.','Web Walker',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('c92b6310-491d-4dde-ae50-2811501ce756'::uuid,'01990b9c-bd39-7ff6-b85d-02672802e040'::uuid,'The spider can climb difficult surfaces, including along ceilings, without needing to make an ability check.','Spider Climb',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO public.traits (id,monster_id,description,title,is_optional,attack_bonus,damage_bonus,damage_dice,damage_type,number_damage_dice,advantage_condition,disadvantage_condition,trait_trigger) VALUES
	 ('ec02924e-1b9f-4936-a8dc-72f2db62d863'::uuid,'01990b9c-c625-7b7e-b7ff-07fcd206faf6'::uuid,'The spined devil makes two attacks with its fork or its tail. Fork. Melee Weapon Attack: +4 to hit, reach 5 ft., one target. Hit: 5 (1d4 + 3) piercing damage. Tail. Melee Weapon Attack: +4 to hit, reach 5 ft., one target. Hit: 5 (1d4 + 3) piercing damage.','Actions',false,4,3,'d4','Piercing',1,NULL,NULL,NULL),
	 ('37bc0e10-0848-4b3f-b5a7-7482bd4b06f9'::uuid,'01990b9c-e45d-7819-b628-3351feb49fdc'::uuid,'Fiendish Restoration. If it dies, the naga returns to life in 1d6 days and regains all its Hit Points. Only a Wish spell can prevent this trait from functioning.','Fiendish Restoration',false,NULL,NULL,'d6',NULL,1,NULL,NULL,'If it dies'),
	 ('c82a3540-08c2-44a9-be4b-60984708d6e6'::uuid,'01990b9d-5f81-7d10-ba9f-0e4240a48ed5'::uuid,'Attack rolls against the mephit are made with Disadvantage unless the mephit has the Incapacitated condition.','Blurred Form',false,NULL,NULL,NULL,NULL,NULL,NULL,'unless the mephit has the Incapacitated condition',NULL),
	 ('d22755d8-80ab-4d9c-8e5b-5a83d634a4b0'::uuid,'01990b9d-5f81-7d10-ba9f-0e4240a48ed5'::uuid,'The mephit explodes when it dies. Dexterity Saving Throw: DC 10, each creature in a 5-foot Emanation originating from the mephit. Failure: 5 (2d4) Fire damage. Success: Half damage.','Death Burst',false,NULL,NULL,'d4','Fire',2,NULL,NULL,'when it dies'),
	 ('1017bb82-b297-4190-beca-671631a08d5e'::uuid,'01990b9d-c819-752c-a16b-d7c5bed6ab33'::uuid,'Immutable Form. The golem can''t shape-shift.','Immutable Form',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('3e7745d9-2cce-47b8-a23f-947ec88575de'::uuid,'01990b9d-c819-752c-a16b-d7c5bed6ab33'::uuid,'Magic Resistance. The golem has Advantage on saving throws against spells and other magical effects.','Magic Resistance',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('2dd6dbdb-23fe-4d4a-bf06-fc8a6add23c5'::uuid,'01990b9d-f6bb-733d-a315-5547bf7fad88'::uuid,'Amphibious. The giant can breathe air and water.','Amphibious',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('0701c854-4eb1-4243-a1e8-2d6d394548c6'::uuid,'01990b9e-1f47-7736-b2c9-33a8b0d9c7c6'::uuid,'Incubus Form. When the succubus finishes a Long Rest, it can shape-shift into an Incubus, using that stat block instead of this one.','Incubus Form',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'When the succubus finishes a Long Rest'),
	 ('03d19828-68e3-42f5-860f-2210a517226b'::uuid,'01990b9e-2eb1-7e96-9c4d-dca36a8a937c'::uuid,'The swarm can occupy another creature''s space and vice versa, and the swarm can move through any opening large enough for a Tiny bat. The swarm can''t regain Hit Points or gain Temporary Hit Points.','Swarm',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('bd94bfd9-8a13-43f6-9fb6-3eaab1996c9b'::uuid,'01990b9e-3e10-79e7-bfdc-99463f610607'::uuid,'Swarm. The swarm can occupy another creature''s space and vice versa, and the swarm can move through any opening large enough for a Tiny creature. The swarm can''t regain Hit Points or gain Temporary Hit Points.','Swarm',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
