	 ('034cd1df-502d-4eec-be1a-f2a9cc82d0ba'::uuid,'01990b9e-45f0-7d66-8f1f-a85da0b39452'::uuid,'The swarm can take 3 actions: 2 with its claws and 1 with its bite.','Actions',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('80cb9932-1689-4eaa-9867-53fd4b70b10a'::uuid,'01990b9e-594b-7099-a5c8-4206f1043f75'::uuid,'Spider Climb. If the swarm has a Climb Speed, the swarm can climb difficult surfaces, including along ceilings, without needing to make an ability check.','Spider Climb',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('e33a67fb-49cb-44c3-a0df-4a89c403e2e2'::uuid,'01990b9e-594b-7099-a5c8-4206f1043f75'::uuid,'Swarm. The swarm can occupy another creature''s space and vice versa, and the swarm can move through any opening large enough for a Tiny insect. The swarm can''t regain Hit Points or gain Temporary Hit Points.','Swarm',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('68182eed-b0a6-4434-9f6a-774dd9b52e51'::uuid,'01990b9e-6684-75de-9f16-eee02ae3a0eb'::uuid,'The swarm of lemures can use its Swarm of Bites. It makes two attacks, one with its bite and one with its claws. If both attacks hit a Medium or smaller target, the target is grappled (escape DC 10), and the lemures swarm has advantage on attack rolls against it. Until this grapple ends, the target is restrained, and the lemures swarm can''t bite another target.','Actions',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('bd2459fd-bd08-4e5f-b0ff-22f05901f43b'::uuid,'01990b9e-7d90-7c8c-bc33-c191c3d55828'::uuid,'Swarm. The swarm can occupy another creature''s space and vice versa, and the swarm can move through any opening large enough for a Tiny piranha. The swarm can''t regain Hit Points or gain Temporary Hit Points.','Swarm',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('d1988b9d-69a4-4437-b20d-2a2564e85dfc'::uuid,'01990b9e-7d90-7c8c-bc33-c191c3d55828'::uuid,'Water Breathing. The swarm can breathe only underwater.','Water Breathing',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('2d8bf236-8507-4787-ab4e-fd67203457e6'::uuid,'01990b9e-89ef-7d2f-8b2b-fb832e11eab9'::uuid,'The swarm can occupy another creature''s space and vice versa, and the swarm can move through any opening large enough for a Tiny rat. The swarm can''t regain Hit Points or gain Temporary Hit Points.','Swarm',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('09bbb3c1-2a87-42dd-a2ff-1b824ad195b9'::uuid,'01990b9e-9b5e-7a25-9ba7-e257b3e5d813'::uuid,'Swarm. The swarm can occupy another creature''s space and vice versa, and the swarm can move through any opening large enough for a Tiny raven. The swarm can''t regain Hit Points or gain Temporary Hit Points.','Swarm',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('a4b47a83-fcfc-4f78-b0e9-54862a5c422b'::uuid,'01990b9e-a1a3-712c-9188-a0ff4fa0eeef'::uuid,'The swarm of stirges can take 3 actions: Multiattack, Blood Drain, and Swarm.','Actions',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('1eabd27f-0e40-42b1-9c13-4374aa016f6a'::uuid,'01990b9e-b0c3-7a4d-aff3-04c5c23964c5'::uuid,'The swarm can occupy another creature''s space and vice versa, and the swarm can move through any opening large enough for a Tiny snake. The swarm can''t regain Hit Points or gain Temporary Hit Points.','Swarm',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO public.traits (id,monster_id,description,title,is_optional,attack_bonus,damage_bonus,damage_dice,damage_type,number_damage_dice,advantage_condition,disadvantage_condition,trait_trigger) VALUES
	 ('926307f2-41e2-4c6b-913d-5f52b4a7a1aa'::uuid,'01990b9f-0c75-797d-80ee-c1134a2e66ca'::uuid,'Reflective Carapace. If the tarrasque is targeted by a Magic Missile spell or a spell that requires a ranged attack roll, roll 1d6. On a 1-5, the tarrasque is unaffected. On a 6, the tarrasque is unaffected and reflects the spell, turning the caster into the target.','Reflective Carapace',false,NULL,NULL,'d6',NULL,1,NULL,NULL,NULL),
	 ('9754518b-cf0d-44ee-99f4-5e30b04bcee9'::uuid,'01990b9f-0c75-797d-80ee-c1134a2e66ca'::uuid,'Siege Monster. The tarrasque deals double damage to objects and structures.','Siege Monster',false,NULL,2,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('a68c5791-4e7c-4fd6-bbaf-dc8c9866a8af'::uuid,'01990b9f-0c75-797d-80ee-c1134a2e66ca'::uuid,'Legendary Resistance (6/Day). If the tarrasque fails a saving throw, it can choose to succeed instead.','Legendary Resistance',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('dc337d49-1e89-468e-bb9d-cd6d548bfab4'::uuid,'01990b9f-0c75-797d-80ee-c1134a2e66ca'::uuid,'Magic Resistance. The tarrasque has Advantage on saving throws against spells and other magical effects.','Magic Resistance',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('21789a15-ec8b-438b-80ec-b00ed8c851a2'::uuid,'01990b9f-2d29-79c5-9dfe-686f0a8a1fa4'::uuid,'Pack Tactics. The tough has Advantage on an attack roll against a creature if at least one of the tough''s allies is within 5 feet of the creature and the ally doesn''t have the Incapacitated condition.','Pack Tactics',false,NULL,NULL,NULL,NULL,NULL,'if at least one of the tough''s allies is within 5 feet of the creature and the ally doesn''t have the Incapacitated condition',NULL,NULL),
	 ('003dafe4-1445-41c1-945f-5fc7beea4738'::uuid,'01990b9f-4c44-74ba-92d8-529597b5b534'::uuid,'Pack Tactics. The tough has Advantage on an attack roll against a creature if at least one of the tough''s allies is within 5 feet of the creature and the ally doesn''t have the Incapacitated condition.','Pack Tactics',false,NULL,NULL,NULL,NULL,NULL,'if at least one of the tough''s allies is within 5 feet of the creature and the ally doesn''t have the Incapacitated condition',NULL,NULL),
	 ('3ac8f7a6-c288-4580-991f-c628cab94ff7'::uuid,'01990b9f-729c-7293-b789-1eec243b8314'::uuid,'Siege Monster. The treant deals double damage to objects and structures.','Siege Monster',false,NULL,2,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('05948ed8-2c48-4b7f-8807-e10a1f4f786e'::uuid,'01990b9f-8941-783a-8d6c-88a22040402f'::uuid,'Melee Weapon Attack: +4 to hit, reach 5 ft., one target. Hit: 4 (1d4 + 2) piercing damage.','Bite',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('452e1be1-7292-40c8-a2d2-683d9bfbbda1'::uuid,'01990b9f-8941-783a-8d6c-88a22040402f'::uuid,'Melee Weapon Attack: +4 to hit, reach 5 ft., one target. Hit: 4 (1d4 + 2) slashing damage.','Claw',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('67eec401-6459-47b4-8bc7-1c5375e02ec4'::uuid,'01990b9f-8941-783a-8d6c-88a22040402f'::uuid,'Any creature that starts its turn within 5 feet of the troglodyte must succeed on a DC 12 Constitution saving throw or be poisoned until the start of the creature''s next turn. On a successful saving throw, the creature is immune to the stench of all troglodytes for 1 hour.','Stench',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO public.traits (id,monster_id,description,title,is_optional,attack_bonus,damage_bonus,damage_dice,damage_type,number_damage_dice,advantage_condition,disadvantage_condition,trait_trigger) VALUES
	 ('bffa1318-5737-4fd9-a4b5-3c29d95b8652'::uuid,'01990b9f-8941-783a-8d6c-88a22040402f'::uuid,'The troglodyte makes three attacks: one with its bite and two with its claws.','Multiattack',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('6498b97d-180a-4c45-b108-36f04e1e4b73'::uuid,'01990b9f-adbc-79b0-950a-332d7bb3236e'::uuid,'Regeneration. The troll regains 15 Hit Points at the start of each of its turns. If the troll takes Acid or Fire damage, this trait doesn''t function on the troll''s next turn. The troll dies only if it starts its turn with 0 Hit Points and doesn''t regenerate.n.','Regeneration',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('ccfc0b0b-7dd0-47f6-9e7f-b84145360447'::uuid,'01990b9f-adbc-79b0-950a-332d7bb3236e'::uuid,'Loathsome Limbs (4/Day). If the troll ends any turn Bloodied and took 15+ Slashing damage during that turn, one of the troll''s limbs is severed, falls into the troll''s space, and becomes a Troll Limb. The limb acts immediately after the troll''s turn. The troll has 1 Exhaustion level for each missing limb, and it grows replacement limbs the next time it regains Hit Points.','Loathsome Limbs',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'If the troll ends any turn Bloodied and took 15+ Slashing damage during that turn'),
	 ('526116df-36e6-47f7-9aa5-66598ca70b1c'::uuid,'01990b9f-c19e-7b96-a3e5-c802b8ab3ccf'::uuid,'Troll Spawn. The limb uncannily has the same senses as a whole troll. If the limb isn''t destroyed within 24 hours, roll 1d12. On a 12, the limb turns into a Troll. Otherwise, the limb withers away.','Troll Spawn',false,NULL,NULL,'d12',NULL,1,NULL,NULL,NULL),
	 ('d129cfe5-f72a-4dc8-9c94-cbb35fb83f77'::uuid,'01990b9f-c19e-7b96-a3e5-c802b8ab3ccf'::uuid,'Regeneration. The limb regains 5 Hit Points at the start of each of its turns. If the limb takes Acid or Fire damage, this trait doesn''t function on the limb''s next turn. The limb dies only if it starts its turn with 0 Hit Points and doesn''t regenerate.','Regeneration',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('a1df1e77-2235-49c0-ab5b-a83533daa09f'::uuid,'01990b9f-cb0d-7fa9-b929-06e4dfa130bb'::uuid,'Actions. Slam. Melee Weapon Attack: +4 to hit, reach 5 ft., one target. Hit: 4 (1d4 + 2) piercing damage.','Actions',false,4,2,'d4','Piercing',1,NULL,NULL,NULL),
	 ('17f1a833-5928-45e2-8152-b57546b2da7c'::uuid,'01990b9f-e836-7ff9-8a67-66236c7ce357'::uuid,'The ultroloth can take 3 legendary actions, choosing from the options below. Only one legendary action option can be used at a time and only at the end of another creature''s turn. The ultroloth regains spent legendary actions at the start of its turn. Teleport. The ultroloth magically teleports, along with any equipment it is wearing or carrying, up to 60 feet to an unoccupied space it can see. Innate Spellcasting (Costs 2 Actions). The ultroloth casts a spell from its list of innate spells, using a spell slot as normal. It can''t cast the same spell two turns in a row. Summon Yugoloth (Costs 3 Actions). The ultroloth summons one yugoloth with a challenge rating of 10 or lower. The summoned yugoloth appears in an unoccupied space within 60 feet of the ultroloth, acts as an ally of the ultroloth, and can''t summon other demons. It remains for 10 minutes, until it or the ultroloth dies, or until the ultroloth dismisses it as an action.','Actions',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('946cea82-3021-4e4a-aeed-380e299c27c6'::uuid,'01990ba0-06f1-7c9c-93d2-d4295bd1b34d'::uuid,'Tunneler. The umber hulk can burrow through solid rock at half its Burrow Speed and leaves a 10-foot-diameter tunnel in its wake.','Tunneler',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('64bf1350-1dd2-4bca-81e9-23282500c8b0'::uuid,'01990ba0-3ed3-7d1b-9f46-aba91aedab20'::uuid,'Legendary Resistance (3/Day). If the unicorn fails a saving throw, it can choose to succeed instead.','Legendary Resistance',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('9aa538b1-97b4-412c-9d1e-e3fbe544d419'::uuid,'01990ba0-3ed3-7d1b-9f46-aba91aedab20'::uuid,'Magic Resistance. The unicorn has Advantage on saving throws against spells and other magical effects.','Magic Resistance',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO public.traits (id,monster_id,description,title,is_optional,attack_bonus,damage_bonus,damage_dice,damage_type,number_damage_dice,advantage_condition,disadvantage_condition,trait_trigger) VALUES
	 ('6556ee94-45d0-4133-9376-b1f00c4b8883'::uuid,'01990ba0-9281-7a49-bbbd-d0b52e3c2c6d'::uuid,'Forbiddance. The vampire can''t enter a residence without an invitation from an occupant.','Forbiddance',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('7358eeb1-24db-4a06-b874-69eb328adc0c'::uuid,'01990ba0-9281-7a49-bbbd-d0b52e3c2c6d'::uuid,'Misty Escape. If the vampire drops to 0 Hit Points outside its resting place, the vampire uses Shape-Shift to become mist (no action required). If it can''t use Shape-Shift, it is destroyed. While it has 0 Hit Points in mist form, it can''t return to its vampire form, and it must reach its resting place within 2 hours or be destroyed. Once in its resting place, it returns to its vampire form and has the Paralyzed condition until it regains any Hit Points, and it regains 1 Hit Point after spending 1 hour there.','Misty Escape',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('8e86adc6-7df6-4e57-897b-3e05b0c8d082'::uuid,'01990ba0-9281-7a49-bbbd-d0b52e3c2c6d'::uuid,'Stake to the Heart. If a weapon that deals Piercing damage is driven into the vampire''s heart while the vampire has the Incapacitated condition in its resting place, the vampire has the Paralyzed condition until the weapon is removed.','Stake to the Heart',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'if a weapon that deals Piercing damage is driven into the vampire''s heart while the vampire has the Incapacitated condition in its resting place'),
	 ('a0d51577-ab13-43b5-b0c2-02140cbb2b53'::uuid,'01990ba0-9281-7a49-bbbd-d0b52e3c2c6d'::uuid,'Vampire Weakness. The vampire has these weaknesses:','Vampire Weakness',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('a373ad19-5f91-477a-8f60-2a62ed00408f'::uuid,'01990ba0-9281-7a49-bbbd-d0b52e3c2c6d'::uuid,'Sunlight. The vampire takes 20 Radiant damage if it starts its turn in sunlight. While in sunlight, it has Disadvantage on attack rolls and ability checks.','Sunlight',false,NULL,NULL,'d20','Radiant',20,NULL,'While in sunlight, it has Disadvantage on attack rolls and ability checks','if it starts its turn in sunlight'),
	 ('ab4c3aa3-f8eb-4c01-9805-ea57dec20f38'::uuid,'01990ba0-9281-7a49-bbbd-d0b52e3c2c6d'::uuid,'Running Water. The vampire takes 20 Acid damage if it ends its turn in running water.','Running Water',false,NULL,NULL,'d20','Acid',20,NULL,NULL,'if it ends its turn in running water'),
	 ('c7decf4b-809d-4156-bb3f-01ad8209b4a6'::uuid,'01990ba0-9281-7a49-bbbd-d0b52e3c2c6d'::uuid,'Legendary Resistance (3/Day, or 4/Day in Lair). If the vampire fails a saving throw, it can choose to succeed instead.','Legendary Resistance',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('f9e0d8c1-c185-47b4-b68b-7f6d5a49f111'::uuid,'01990ba0-9281-7a49-bbbd-d0b52e3c2c6d'::uuid,'Spider Climb. The vampire can climb difficult surfaces, including along ceilings, without needing to make an ability check.','Spider Climb',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('c78dbdba-c370-4542-8372-ce82f84c0447'::uuid,'01990ba0-b815-75b3-9f30-91a807c062a9'::uuid,'Vampiric Connection. While the familiar and its vampire master are on the same plane of existence, the vampire can communicate with the familiar telepathically, and the vampire can perceive through the familiar''s senses.','Vampiric Connection',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('4f14e43e-760f-4eeb-b43b-17d692a5bb20'::uuid,'01990ba0-d6c7-7dca-bc53-4a43adf6b054'::uuid,'The vampire nightbringer can use its action to make a bite attack. It can then use its bonus action to make a claw attack.','Actions',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
