	 ('88f6233a-f66e-413f-9eda-99ba303576fe'::uuid,'01990ba1-056f-79ba-8588-c0862f05a8e4'::uuid,'The vampire is destroyed if a weapon that deals Piercing damage is driven into the vampire''s heart while the vampire has the Incapacitated condition.','Stake to the Heart',false,NULL,NULL,NULL,'Piercing',NULL,NULL,NULL,'a weapon that deals Piercing damage is driven into the vampire''s heart while the vampire has the Incapacitated condition'),
	 ('aa7d709f-30d9-442a-b2e5-a391f95c2cf9'::uuid,'01990ba1-056f-79ba-8588-c0862f05a8e4'::uuid,'The vampire takes 20 Acid damage if it ends its turn in running water.','Running Water',false,NULL,NULL,'d20','Acid',20,NULL,NULL,'ends its turn in running water'),
	 ('d77d627e-000f-4086-8c46-73ee01bfeee6'::uuid,'01990ba1-056f-79ba-8588-c0862f05a8e4'::uuid,'The vampire takes 20 Radiant damage if it starts its turn in sunlight. While in sunlight, it has Disadvantage on attack rolls and ability checks.','Sunlight',false,NULL,NULL,'d20','Radiant',20,NULL,'While in sunlight','starts its turn in sunlight'),
