	 ('2161edf2-4618-4301-9fde-38bd24af3e17'::uuid,'01990ba1-65b6-7a75-a157-ead1d511ef35'::uuid,'Magic Resistance. The vrock has Advantage on saving throws against spells and other magical effects.','Magic Resistance',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('e54c849f-566a-49a8-97af-199f987010da'::uuid,'01990ba1-65b6-7a75-a157-ead1d511ef35'::uuid,'Demonic Restoration. If the vrock dies outside the Abyss, its body dissolves into ichor, and it gains a new body instantly, reviving with all its Hit Points somewhere in the Abyss.','Demonic Restoration',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('ce6abcdc-650a-468e-bd83-ba82f0c31efa'::uuid,'01990ba1-747c-7190-af9c-d8e426c92d24'::uuid,'Pack Tactics. The vulture has Advantage on an attack roll against a creature if at least one of the vulture''s allies is within 5 feet of the creature and the ally doesn''t have the Incapacitated condition.','Pack Tactics',false,NULL,NULL,NULL,NULL,NULL,'if at least one of the vulture''s allies is within 5 feet of the creature and the ally doesn''t have the Incapacitated condition',NULL,NULL),
	 ('22a63da0-bd21-4eff-b49c-27dbae64fb08'::uuid,'01990ba1-cf18-7896-b425-2cf5a117af2c'::uuid,'Pack Tactics. The warrior has Advantage on an attack roll against a creature if at least one of the warrior''s allies is within 5 feet of the creature and the ally doesn''t have the Incapacitated condition.','Pack Tactics',false,NULL,NULL,NULL,NULL,NULL,'if at least one of the warrior''s allies is within 5 feet of the creature and the ally doesn''t have the Incapacitated condition',NULL,NULL);
