	 ('f05e9a2b-e4f3-49cb-a4e5-d50dd6517546'::uuid,'01990ba2-01e5-7e62-a23b-bc4f7f433f37'::uuid,'The water elemental makes two slam attacks.','Actions',false,NULL,NULL,'d8','Bludgeoning',2,NULL,NULL,NULL),
	 ('121b0244-0e0a-4e14-b4f2-42ab1ef17913'::uuid,'01990ba2-e045-7df6-864d-b0a83c748250'::uuid,'Pack Tactics. The werewolf has Advantage on an attack roll against a creature if at least one of the werewolf''s allies is within 5 feet of the creature and the ally doesn''t have the Incapacitated condition.','Pack Tactics',false,NULL,NULL,NULL,NULL,NULL,'if at least one of the werewolf''s allies is within 5 feet of the creature and the ally doesn''t have the Incapacitated condition',NULL,NULL),
	 ('8d56d59f-9cfc-426f-9236-1981de88b577'::uuid,'01990ba3-3ff6-7d5c-8664-486a196fb755'::uuid,'Ice Walk. The dragon can move across and climb icy surfaces without needing to make an ability check. Additionally, Difficult Terrain composed of ice or snow doesn''t cost it extra movement.','Ice Walk',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('43e3c91b-9e01-4cfa-847c-9d9e01efc415'::uuid,'01990ba3-5aed-79e1-ae68-bd05dcb45c94'::uuid,'Sunlight Sensitivity. While in sunlight, the wight has Disadvantage on ability checks and attack rolls.','Sunlight Sensitivity',false,NULL,NULL,NULL,NULL,NULL,NULL,'While in sunlight',NULL),
	 ('4af6a3c2-224a-4920-9ec5-416a91060a61'::uuid,'01990ba3-7008-7efe-b3a4-73087f811671'::uuid,'Pack Tactics. The wolf has Advantage on an attack roll against a creature if at least one of the wolf''s allies is within 5 feet of the creature and the ally doesn''t have the Incapacitated condition.','Pack Tactics',false,NULL,NULL,NULL,NULL,NULL,'if at least one of the wolf''s allies is within 5 feet of the creature and the ally doesn''t have the Incapacitated condition',NULL,NULL),
	 ('4f30cdfd-a9cf-4b58-adc9-5c203fcbbac1'::uuid,'01990ba3-8ef5-7f92-9108-2a6e7eb361a0'::uuid,'Pack Tactics. The wolf has Advantage on attack rolls against a creature if at least one of the wolf''s allies is within 5 feet of the creature and the ally doesn''t have the Incapacitated condition.','Pack Tactics',false,NULL,NULL,NULL,NULL,NULL,'if at least one of the wolf''s allies is within 5 feet of the creature and the ally doesn''t have the Incapacitated condition',NULL,NULL),
	 ('ba0ad260-940c-4f9a-b24b-8e4420ae6a09'::uuid,'01990ba3-a9eb-7e67-bd83-7158f0741ba0'::uuid,'Incorporeal Movement. The wraith can move through other creatures and objects as if they were Difficult Terrain. It takes 5 (1d10) Force damage if it ends its turn inside an object.','Incorporeal Movement',false,NULL,NULL,'d10','Force',1,NULL,NULL,'if it ends its turn inside an object'),
	 ('e51dc1f2-7b50-4086-8b62-89d305084984'::uuid,'01990ba3-a9eb-7e67-bd83-7158f0741ba0'::uuid,'Sunlight Sensitivity. While in sunlight, the wraith has Disadvantage on ability checks and attack rolls.','Sunlight Sensitivity',false,NULL,NULL,NULL,NULL,NULL,NULL,'While in sunlight',NULL),
	 ('1e7800b3-19e0-442e-965b-e30edbbf18a5'::uuid,'01990ba3-de82-7b6d-aa69-e8c531983283'::uuid,'Treasure Sense. The xorn can pinpoint the location of precious metals and stones within 60 feet of itself.','Treasure Sense',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('c413dc8b-2762-48a1-a19e-48c9e5bc4b40'::uuid,'01990ba3-de82-7b6d-aa69-e8c531983283'::uuid,'Earth Glide. The xorn can burrow through nonmagical, unworked earth and stone. While doing so, the xorn doesn''t disturb the material it moves through.','Earth Glide',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO public.traits (id,monster_id,description,title,is_optional,attack_bonus,damage_bonus,damage_dice,damage_type,number_damage_dice,advantage_condition,disadvantage_condition,trait_trigger) VALUES
	 ('db0c1825-165f-49f6-a5ea-609a04862a96'::uuid,'01990ba4-0775-7c93-a9c9-7f5a06bb764b'::uuid,'Fear of Fire. If the yeti takes Fire damage, it has Disadvantage on attack rolls and ability checks until the end of its next turn.','Fear of Fire',false,NULL,NULL,NULL,'Fire',NULL,NULL,'it has Disadvantage on attack rolls and ability checks until the end of its next turn','If the yeti takes Fire damage'),
	 ('5bd2088a-3d63-4be8-8003-c2cc218cf35e'::uuid,'01990ba4-1890-76bb-b10f-6df9bdd65981'::uuid,'The yochlol can take 2 legendary actions, choosing from the options below. Only one legendary action option can be used at a time and only at the end of another creature''s turn. The yochlol regains spent legendary actions at the start of its turn.','Actions',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('5476d7de-167e-40ce-ae99-da5fffd1f423'::uuid,'01990ba4-378c-7e18-9d1c-5dd1b073934f'::uuid,'Amphibious. The dragon can breathe air and water.','Amphibious',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('bc6ea596-d750-4285-aa5e-0328c3c817df'::uuid,'01990ba4-869c-7210-8f30-7961ff114b30'::uuid,'Amphibious. The dragon can breathe air and water.','Amphibious',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('9941f03c-12cb-40cb-9a67-830fa8d55737'::uuid,'01990ba5-07d4-7327-a197-220f29438c1f'::uuid,'The young remorhaz makes three attacks: one with its bite and two with its tail. It can also use its Swallow. Bite. Melee Weapon Attack: +9 to hit, reach 10 ft., one target. Hit: 40 (6d10 + 7) piercing damage. Tail. Melee Weapon Attack: +9 to hit, reach 10 ft. one target. Hit: 24 (4d8 + 6) bludgeoning damage. Swallow. The remorhaz makes one bite attack against a Medium or smaller creature it is grappling. If the attack hits, that creature takes the bite''s damage and is swallowed, and the grapple ends. While swallowed, the creature is blinded and restrained, it has total cover against attacks and other effects outside the remorhaz, and it takes 21 (6d6) acid damage at the start of each of the remorhaz''s turns. If the remorhaz takes 30 damage or more on a single turn from a creature inside it, the remorhaz must succeed on a DC 15 Constitution saving throw at the end of that turn or regurgitate the swallowed creature, which falls prone in a space within 10 feet of the remorhaz. If the remorhaz dies, a swallowed creature is no longer restrained by it and can escape from the corpse using 15 feet of movement, exiting prone.','Actions',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('4fde9cb8-ddf8-41aa-8bed-668a5a97ef9d'::uuid,'01990ba5-3179-7370-806a-46800b48c495'::uuid,'Ice Walk. The dragon can move across and climb icy surfaces without needing to make an ability check. Additionally, Difficult Terrain composed of ice or snow doesn''t cost it extra movement.','Ice Walk',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('b754d528-becc-4df2-b87c-074ad49b99c4'::uuid,'01990ba5-40a7-754d-abee-531bf4e05ef7'::uuid,'The yuan-ti abomination can take 3 legendary actions, choosing from the options below. Only one legendary action option can be used at a time and only at the end of another creature''s turn. The yuan-ti abomination regains spent legendary actions at the start of its turn. Bite. Melee Weapon Attack: +9 to hit, reach 10 ft., one target. Hit: 12 (2d6 + 5) piercing damage plus 7 (2d6) poison damage. Constrict. The yuan-ti abomination makes one attack with its tail. Tail. Melee Weapon Attack: +9 to hit, reach 10 ft., one creature. Hit: 13 (2d8 + 5) bludgeoning damage plus 17 (5d6) poison damage, and the target is grappled (escape DC 15). Until this grapple ends, the target is restrained, and the yuan-ti can''t constrict another target. Cast a Spell (Costs 2 Actions). The yuan-ti abomination casts a spell from its list of prepared spells, using a spell slot as normal.','Actions',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('6165139e-08bd-47c5-b2c3-e07de302d903'::uuid,'01990ba5-488e-721d-82b5-0a8f25d90b0a'::uuid,'The yuan-ti makes two melee attacks, one with its bite and one with its constrict. Bite: Melee Weapon Attack: +6 to hit, reach 5 ft., one target. Hit: 7 (1d6 + 4) piercing damage. Constrict: Melee Weapon Attack: +6 to hit, reach 5 ft., one creature. Hit: 10 (2d6 + 4) bludgeoning damage, and the target is grappled (escape DC 14). Until this grapple ends, the target is restrained, and the yuan-ti can''t constrict another target.','Actions',false,6,4,'d6','Piercing',1,NULL,NULL,NULL),
	 ('8b9ff74e-3187-4de0-89fc-6ab95a19ffef'::uuid,'01990ba5-5883-7540-9b42-f073451d929e'::uuid,'Undead Fortitude. If damage reduces the zombie to 0 Hit Points, it must make a Constitution saving throw (DC 5 plus the damage taken) unless the damage is Radiant or from a Critical Hit. On a successful save, the zombie drops to 1 Hit Point instead.','Undead Fortitude',false,NULL,NULL,NULL,'Radiant',NULL,NULL,NULL,'If damage reduces the zombie to 0 Hit Points'),
	 ('08967983-9b66-4b19-9fbe-5107fe1804aa'::uuid,'01990bad-ef51-7b44-bdca-f7a4fcf1190e'::uuid,'Incorporeal Movement. The wisp can move through other creatures and objects as if they were Difficult Terrain. It takes 5 (1d10) Force damage if it ends its turn inside an object.','Incorporeal Movement',false,NULL,NULL,'d10','Force',1,NULL,NULL,'ends its turn inside an object');
INSERT INTO public.traits (id,monster_id,description,title,is_optional,attack_bonus,damage_bonus,damage_dice,damage_type,number_damage_dice,advantage_condition,disadvantage_condition,trait_trigger) VALUES
	 ('a88e0a76-cb08-43ef-9f23-27eceb33c318'::uuid,'01990bad-ef51-7b44-bdca-f7a4fcf1190e'::uuid,'Ephemeral. The wisp can''t wear or carry anything.','Ephemeral',false,NULL,NULL,NULL,'Force',NULL,NULL,NULL,NULL),
	 ('dddae832-dbeb-4f0e-8ea1-fe4f0a6ea1d2'::uuid,'01990bad-ef51-7b44-bdca-f7a4fcf1190e'::uuid,'Illumination. The wisp sheds Bright Light in a 20-foot radius and Dim Light for an additional 20 feet.','Illumination',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('0c2fb2c6-2562-4d90-80d3-7fdd8c70fc74'::uuid,'01990bc2-cfa8-70df-b173-7a8f45c7a69a'::uuid,'The yuan-ti malison makes two melee attacks, one with its scimitar and one with its bite, or two ranged attacks with its longbow. It can use its bite as a bonus action after it makes a melee attack with its scimitar.','Actions',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('b987798d-aa23-41f9-b758-cfb866d740b4'::uuid,'01990bc3-f466-7e3b-ab27-409bedb12abe'::uuid,'The yuan-ti malison makes two melee attacks, one with its scimitar and one with its bite, or two ranged attacks with its longbow. It can use its bite as a bonus action after making its scimitar attack.','Actions',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('0df303b2-2fc9-4638-b18f-82cdc4b8cef8'::uuid,'01990bbd-65b1-7982-a900-580d5c5dee1f'::uuid,'The yuan-ti malison makes two melee attacks, or it makes one ranged attack with its longbow. It can use its bite and constrict in the same round, but only against different targets.','Actions',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('834eb2c6-d6a5-4599-a99f-3426c1d23bb9'::uuid,'01990b97-2583-7b20-a7dc-0ef5472878c6'::uuid,'Spider Climb. The spider can climb difficult surfaces, including along ceilings, without needing to make an ability check.','Spider Climb',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('965566bd-ce69-443f-8d11-e193fab38355'::uuid,'01990b97-2583-7b20-a7dc-0ef5472878c6'::uuid,'Ethereal Sight. The spider can see 60 feet into the Ethereal Plane while on the Material Plane and vice versa.','Ethereal Sight',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('c063c0bc-9b16-46f5-a970-ff050345779f'::uuid,'01990b97-2583-7b20-a7dc-0ef5472878c6'::uuid,'Web Walker. The spider ignores movement restrictions caused by webs, and the spider knows the location of any other creature in contact with the same web.','Web Walker',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('ed01e1e5-5c2e-4b04-ba61-f3e70faa0337'::uuid,'01990ba3-5f04-78b0-9430-6fbafe10933f'::uuid,'The winged kobold makes two attacks: one with its dagger and one with its sling.','Actions',false,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
